$(document).ready(function( )
{
	$(".accordian").accordion(
	{
		collapsible  :  false,
		header       :  "h3",
		heightStyle  :  "content",
		icons        :  { header:"ui-icon-circle-arrow-e", activeHeader:"ui-icon-circle-arrow-s" }
	});


	$("img.who, img.details").tipTip( );


	if ($("#BtnProfile").length > 0)
		$("#BtnProfile").button({ icons:{ primary:'ui-icon-pencil' } });

	if ($("#BtnConcession").length > 0)
		$("#BtnConcession").button({ icons:{ primary:'ui-icon-pencil' } });

	if ($("#BtnFee").length > 0)
		$("#BtnFee").button({ icons:{ primary:'ui-icon-plusthick' } });

	if ($("#BtnSms").length > 0)
		$("#BtnSms").button({ icons:{ primary:'ui-icon-mail-open' } });

	if ($("#BtnNotification").length > 0)
		$("#BtnNotification").button({ icons:{ primary:'ui-icon-alert' } });

	if ($("#BtnWrite").length > 0)
		$("#BtnWrite").button({ icons:{ primary:'ui-icon-comment' } });

	if ($("#BtnLogin").length > 0)
		$("#BtnLogin").button({ icons:{ primary:'ui-icon-key' } });

	if ($("#BtnDocument").length > 0)
		$("#BtnDocument").button({ icons:{ primary:'ui-icon-folder-collapsed' } });



	$("#BtnProfile").click(function( )
	{
		var iStudentId = $(this).attr("rel");

		$.colorbox({ href:("students/edit-student.php?StudentId=" + iStudentId + "&Index=-1"), width:"950px", maxWidth:"90%", height:"730px", maxHeight:"90%", iframe:true, opacity:"0.50", overlayClose:false });
	});


	$("#BtnConcession").click(function( )
	{
		var iStudentId = $(this).attr("rel");

		$.colorbox({ href:("students/fee-concession.php?StudentId=" + iStudentId), width:"450px", height:"550px", iframe:true, opacity:"0.50", overlayClose:false });
	});


	$("#BtnFee").click(function( )
	{
		var iStudentId = $(this).attr("rel");

		$.colorbox({ href:("students/custom-fee.php?StudentId=" + iStudentId), width:"900px", height:"650px", maxHeight:"85%", iframe:true, opacity:"0.50", overlayClose:false });
	});	


	$("#BtnSms").click(function( )
	{
		var iStudentId = $(this).attr("rel");

		$.colorbox({ href:("students/send-sms.php?StudentId=" + iStudentId), width:"420px", height:"450px", iframe:true, opacity:"0.50", overlayClose:false });
	});


	$("#BtnNotification").click(function( )
	{
		var iStudentId = $(this).attr("rel");

		$.colorbox({ href:("students/send-app-notification.php?StudentId=" + iStudentId), width:"700px", height:"530px", iframe:true, opacity:"0.50", overlayClose:false });
	});	


	$("#BtnWrite").click(function( )
	{
		var iStudentId = $(this).attr("rel");

		$.colorbox({ href:("students/write-comments.php?StudentId=" + iStudentId), width:"550px", height:"450px", iframe:true, opacity:"0.50", overlayClose:false });
	});


	$("#BtnLogin").click(function( )
	{
		var iStudentId = $(this).attr("rel");

		$.colorbox({ href:("students/manage-login.php?StudentId=" + iStudentId), width:"420px", height:"380px", iframe:true, opacity:"0.50", overlayClose:false });
	});


	$("#BtnDocument").click(function( )
	{
		var iStudentId = $(this).attr("rel");

		$.colorbox({ href:("students/add-document.php?StudentId=" + iStudentId), width:"500px", height:"400px", iframe:true, opacity:"0.50", overlayClose:false });
	});


	$(".picture a img").click(function( )
	{
		var sUrl = $(this).parent( ).attr("href");

		$.colorbox({ href:sUrl, opacity:"0.50", maxWidth:"90%", maxHeight:"90%", overlayClose:true });

		return false;
	});


	$(document).on("click", "#tabs-6 #Settlements .icnView", function(event)
	{
		var iSettlementId = this.id;

		$.colorbox({ href:("billing/view-final-settlement.php?SettlementId=" + iSettlementId), width:"800px", height:"550px", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});


	$(document).on("click", "#tabs-6 #FeeBills .icnEdit", function(event)
	{
		var iFeeId = this.id;

		$.colorbox({ href:("billing/edit-fee-due-date.php?FeeId=" + iFeeId + "&Profile=Y"), width:"90%", maxWidth:"1100px", height:"90%", maxHeight:"500px", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});


	$(document).on("click", "#tabs-6 #FeeBills .icnView", function(event)
	{
		var iFeeId = this.id;

		$.colorbox({ href:("billing/view-fee.php?FeeId=" + iFeeId), width:"900px", height:"520px", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});


	$(document).on("click", "#tabs-6 .icnPrint", function(event)
	{
		var iFeeId = this.id;


		$.post("ajax/billing/print-fee-receipt.php",
			{ FeeId:iFeeId },

			function (sResponse)
			{
				var sParams = sResponse.split("|-|");

				showMessage("#PageMsg", sParams[0], sParams[1]);
			},

			"text");


		event.stopPropagation( );
	});	


	$(document).on("click", "#Concessions img.view", function(event)
	{
		var iConcessionId = this.id;

		$.colorbox({ href:("billing/view-fee-concession.php?ConcessionId=" + iConcessionId), width:"900px", height:"60%", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});	


	$(document).on("click", "#Concessions img.delete", function(event)
	{
		var iStudentId    = $(this).attr("rel");
		var iConcessionId = $(this).attr("id");

		if (iStudentId == "" || iConcessionId == "")
			return;


		$("#DeleteConcession").dialog( { resizable : false,
		                                 width     : 420,
		                                 height    : 110,
		                                 modal     : true,
		                                 buttons   : { "Delete" : function( )
		                                                          {
																	$.post("ajax/students/delete-concession.php",
																		{ StudentId:iStudentId, ConcessionId:iConcessionId },

																		function (sResponse)
																		{
																			var sParams = sResponse.split("|-|");


																			showMessage("#PageMsg", sParams[0], sParams[1]);

																			if (sParams[0] == "success")
																			{
																				$("#Concessions img.delete").remove( );

																				if ($("#BtnConcession").length > 0)
																					$("#BtnConcession").removeClass("hidden");

																				if (sParams[2] == "0")
																					updateConcession(iStudentId);
																			}
																		},

																		"text");

		                                                      	    	$(this).dialog("close");
		                                                          },

		                                                Cancel  : function( )
		                                                          {
		                                                            	$(this).dialog("close");
		                                                          }
		                                          }
		                            });
	});



	$(document).on("click", ".comment img.delete", function( )
	{
		var iStudentId = $(this).attr("rel");
		var iCommentId = $(this).attr("id");

		if (iStudentId == "" || iCommentId == "")
			return;

		$("#DeleteComments").dialog( { resizable : false,
		                               width     : 420,
		                               height    : 110,
		                               modal     : true,
		                               buttons   : { "Delete" : function( )
		                                                        {
																	$.post("ajax/students/delete-comments.php",
																		{ StudentId:iStudentId, CommentId:iCommentId },

																		function (sResponse)
																		{
																			var sParams = sResponse.split("|-|");


																			showMessage("#PageMsg", sParams[0], sParams[1]);

																			if (sParams[0] == "success")
																			{
																				$("#Comment" + iCommentId).remove( );

																				if ($("#tabs-8 .comment").length == 0)
																					$("#tabs-8").html('<div class="info noHide">No Comment made yet!</div>');
																			}
																		},

																		"text");

		                                                      	    	$(this).dialog("close");
		                                                        },

		                                              Cancel  : function( )
		                                                        {
		                                                            	$(this).dialog("close");
		                                                        }
		                                          }
		                            });
	});


	$(document).on("click", "#tabs-7 img.icnDelete", function( )
	{
		var iStudentId  = $(this).attr("rel");
		var iDocumentId = $(this).attr("id");

		if (iStudentId == "" || iDocumentId == "")
			return;


		$("#DeleteDocument").dialog( { resizable : false,
		                                 width     : 450,
		                                 height    : 110,
		                                 modal     : true,
		                                 buttons   : { "Delete" : function( )
		                                                          {
																	$.post("ajax/students/delete-document.php",
																		{ StudentId:iStudentId, DocumentId:iDocumentId },

																		function (sResponse)
																		{
																			var sParams = sResponse.split("|-|");


																			showMessage("#PageMsg", sParams[0], sParams[1]);

																			if (sParams[0] == "success")
																				updateDocuments(iStudentId);
																		},

																		"text");

		                                                      	    	$(this).dialog("close");
		                                                          },

		                                                Cancel  : function( )
		                                                          {
		                                                            	$(this).dialog("close");
		                                                          }
		                                          }
		                            });
	});
});


function updateFeeBills(iStudentId)
{
	$.post("ajax/students/get-fee-bills.php",
		{ StudentId:iStudentId },

		function (sResponse)
		{
			$("#tabs-6").html(sResponse);


			$("#tabs-6 .accordian").accordion(
			{
				collapsible  :  false,
				header       :  "h3",
				heightStyle  :  "content",
				icons        :  { header:"ui-icon-circle-arrow-e", activeHeader:"ui-icon-circle-arrow-s" }
			});


			$("#tabs-6 img.details").tipTip( );
		},

		"text");
}


function updateConcession(iStudentId)
{
	$("#BtnConcession").addClass("hidden");

	$.post("ajax/students/get-concessions.php",
		{ StudentId:iStudentId },

		function (sResponse)
		{
			$("#Concessions").html(sResponse);
			$("#Concessions img.who").tipTip( );
		},

		"text");
}


function updateDocuments(iStudentId)
{
	$.post("ajax/students/get-documents.php",
		{ StudentId:iStudentId },

		function (sResponse)
		{
			$("#tabs-7 .grid").html(sResponse);
			$("#tabs-7 img.who").tipTip( );
		},

		"text");
}


function updateComments(iStudentId)
{
	$.post("ajax/students/get-comments.php",
		{ StudentId:iStudentId },

		function (sResponse)
		{
			$("#tabs-8 .info").remove( );
			$("#tabs-8").html(sResponse);

			$(".comment img.who").tipTip( );
		},

		"text");
}

