$(document).ready(function( )
{
	$("#frmReport #BtnExport").button({ icons:{ primary:'ui-icon-print' } });

	$("#frmSearch #BtnSearch").button({ icons:{ primary:'ui-icon-search' } });
	$("#frmSearch #BtnReset").button({ icons:{ primary:'ui-icon-refresh' } });

	$("#frmRecord #BtnClose").button({ icons:{ primary:'ui-icon-closethick' } });
	$("#frmRecord #BtnDelete").button({ icons:{ primary:'ui-icon-trash' } });
	
	$("#BtnShow").button({ icons:{ primary:'ui-icon-refresh' } });
	$("#BtnExport").button({ icons:{ primary:'ui-icon-disk' } });


	$("#txtRptFromDate, #txtRptToDate, #txtDate").datepicker(
	{
		showOn          : "both",
		buttonImage     : "images/icons/calendar.gif",
		buttonImageOnly : true,
		dateFormat      : "yy-mm-dd"
	});


	$(".time input").timepicker(
	{
		showButtonPanel : false,
		ampm            : true,
		showSecond      : false,
		showMillisec    : false,
		stepHour        : 1,
		stepMinute      : 1,
		hourMin         : 7,
		hourMax         : 19,
		hourGrid        : 4,
		minuteGrid      : 14,
		timeFormat      : "hh:mm TT"
	});

	
	$(".time").click(function( )
	{
		if ($(this).find("input").attr("disabled") == false)
			$(this).find("input").trigger("focus");
	});



	$("#BtnShow").click(function( )
	{
		$.post("ajax/students/get-attendance-summary.php",
			{ Date:$("#txtDate").val( ) },

			function (sResponse)
			{
				$("#Summary").html(sResponse);
			},

			"text");
	});
	
	
	$("#BtnExport").click(function( )
	{
		document.location = ($("#BtnExport").attr("rel") + "?Date=" + $("#txtDate").val( ));
	});
	
	
	
	$("#frmReport #ddRptSchool").change(function( )
	{
		getClassSectionsList("#frmReport #ddRptSchool", "#frmReport #ddRptClass");
	});


	$("#frmReport #ddRptSchool, #frmReport #ddRptSession, #frmReport #ddRptClass").change(function( )
	{
		getStudentsList("#frmReport #ddRptSchool", "#frmReport #ddRptSession", "#frmReport #ddRptClass", "#frmReport #ddRptStudent");
	});
	
	$("#frmReport #ddRptClass").change(function( )
	{
		getAttendanceSubjectsList("#frmReport #ddRptClass", "#frmReport #ddRptSubject", "#frmReport #RptSubject");
	});	


	$("#frmReport").submit(function( )
	{
		var objFV = new FormValidator("frmReport", "ReportMsg");

		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;

		if (!objFV.validate("ddSession", "B", "Please select the Session."))
			return false;

		if (!objFV.validate("ddClass", "B", "Please select the Class/Section."))
			return false;
			
		if ($("#frmReport #RptSubject option").length > 1)
		{
			if (!objFV.validate("ddSubject", "B", "Please select the Subject."))
				return false;
		}

		if (!objFV.validate("txtFromDate", "B", "Please select the From Date."))
			return false;

		if (!objFV.validate("txtToDate", "B", "Please select the To Date."))
			return false;


		$("#frmReport #BtnExport").attr('disabled', true);
		$("#ReportMsg").hide( );

		setTimeout(function( ) { $("#frmReport #BtnExport").attr('disabled', false); }, 30000);
	});




	$("#frmSearch #ddSchool").change(function( )
	{
		getClassSectionsList("#frmSearch #ddSchool", "#frmSearch #ddClass");
	});


	$("#frmSearch #ddSchool, #frmSearch #ddSession, #frmSearch #ddClass").change(function( )
	{
		getStudentsList("#frmSearch #ddSchool", "#frmSearch #ddSession", "#frmSearch #ddClass", "#frmSearch #ddStudent", "A");
	});


	$("#frmSearch #ddClass").change(function( )
	{
		getAttendanceSubjectsList("#frmSearch #ddClass", "#frmSearch #ddSubject", "#frmSearch #Subject");
	});
	

	$("#frmSearch #ddMonth, #frmSearch #ddYear").change(function( )
	{
		var iMonth = parseInt($("#frmSearch #ddMonth").val( ));
		var iYear  = parseInt($("#frmSearch #ddYear").val( ));
		
		var iDays = new Date(iYear, iMonth, 0).getDate( );
		
		var iSelectedDay = $("#frmSearch #ddDay").val( );
		var sDayOptions  = ("<option value=''></option>");
		
		for (var i = 1; i <= iDays; i ++)
			sDayOptions += ("<option value='" + i + "'>" + i +"</option>");
		
		$("#frmSearch #ddDay").html(sDayOptions);
		$("#frmSearch #ddDay").val(iSelectedDay);
	});


	$("#frmSearch #BtnReset").click(function( )
	{
		$("#frmSearch")[0].reset( );
		$("#SearchMsg").hide( );
		$("#frmSearch #Subject").hide( );

		clearList("#frmSearch #ddSubject");
		clearList("#frmSearch #ddStudent");

		if ($("#frmSearch select#ddSchool").length > 0)
		{
			clearList("#frmSearch #ddClass");

			$("#frmSearch #ddSchool").focus( );
		}

		else
			$("#frmSearch #ddSession").focus( );

		return false;
	});


	$("#frmSearch").submit(function( )
	{
		var objFV = new FormValidator("frmSearch", "SearchMsg");


		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;

		if (!objFV.validate("ddSession", "B", "Please select the Session."))
			return false;

		if (!objFV.validate("ddClass", "B", "Please select the Class/Section."))
			return false;
			
		if ($("#frmSearch #Subject option").length > 1 && $("#frmSearch #Subject").css("display") == "block")
		{
			if (!objFV.validate("ddSubject", "B", "Please select the Subject."))
				return false;
		}


		$("#BtnSearch").attr('disabled', true);
		$("#SearchMsg").hide( );
	});




	var iWinWidth  = ($(window).width( ) - 115);
	var iWinHeight = 700;
	
	if ($("#frmRecord .grid").height( ) < 700)
		iWinHeight = ($("#frmRecord .grid").height( ) + 9);
		
	
	$("#frmRecord #TblAttendance").fxdHdrCol(
	{
		fixedCols  :  2,
		width      :  iWinWidth,
		height     :  iWinHeight,
		sort       :  false,
		colModal   :  eval($("#FixedTable").val( ))
	});
	
	
	$("#frmRecord #BtnClose").click(function( )
	{
		$("#RecordMsg").hide( );
		
		document.location = $(this).attr("rel");

		return false;
	});


	$("#frmRecord .attendance").click(function( )
	{
		var iIndex = $(this).attr("id").replace("rbStatusP", "").replace("rbStatusA", "").replace("rbStatusL", "").replace("rbStatusH", "");

		if ($(this).val( ) == "P")
		{
			$("#frmRecord #txtTime" + iIndex).attr("disabled", false);

			if ($("#frmRecord #txtTime" + iIndex).val( ) == "")
				$("#frmRecord #txtTime" + iIndex).val($("#frmRecord #txtTime" + iIndex).attr("rel"));
		}

		else
			$("#frmRecord #txtTime" + iIndex).attr("disabled", true);
	});


	$("#frmRecord .header a.all").click(function( )
	{
		var iStudents = parseInt($("#frmRecord #Students").val( ));
		var sType     = $(this).attr("id");

		for (var i = 0; i < iStudents; i ++)
			$("#frmRecord #" + sType + i).trigger("click");
	
		return false;
	});
	
	
	$("#frmRecord select.all").change(function( )
	{
		var iStudents = parseInt($("#frmRecord #Students").val( ));
		var iDay      = parseInt($(this).attr("id").replace("All", ""));

		for (var i = 0; i < iStudents; i ++)
		{
			if ($("#frmRecord #ddStatus" + i + "_" + iDay).val( ) != "L")
				$("#frmRecord #ddStatus" + i + "_" + iDay).val($(this).val( ));
		}
	});
	
	
	$("#frmRecord").submit(function( )
	{
		var objFV  = new FormValidator("frmRecord", "RecordMsg");


		$(".ft_container table.ft_rc").remove( );
		$(".ft_container div.ft_cwrapper").remove( );
		$(".ft_container div.ft_rwrapper").remove( );


		$("#BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});



	$("#frmRecord #BtnDelete").click(function( )
	{
		$("#ConfirmDelete").dialog( { resizable : false,
									  width     : 420,
									  height    : 110,
									  modal     : true,
									  buttons   : { "Delete" : function( )
															   {
																	$("#frmDelete").submit( );

																	$(this).dialog("close");
															   },

													Cancel  : function( )
															  {
																	$(this).dialog("close");
															  }
										  }
								});

		return false;
	});


	$(".details").tipTip( );
});

