$(document).ready(function( )
{
	$(".school").click(function( )
	{
		getClassSectionsList(".school", "#Classes", "", "M");
		getStudentsList(".school", "#ddSession", ".class", "#Students", $("#ddStatus").val( ), "M", "Y");
	});


	$("#ddSession, #ddStatus").change(function( )
	{
		getStudentsList(".school", "#ddSession", ".class", "#Students", $("#ddStatus").val( ), "M", "Y");
	});


	$(document).on("click", ".class", function( )
	{
		getStudentsList(".school", "#ddSession", ".class", "#Students", $("#ddStatus").val( ), "M", "Y");
	});
	


	$("#BtnReset").click(function( )
	{
		$('#frmRecord')[0].reset( );
		$("#RecordMsg").hide( );

		$("#Classes").html("");
		$("#Students").html("");

		return false;
	});


	$("span a").click(function( )
	{
		var sData   = $(this).attr("rel");
		var sParams = sData.split("|");

		$("." + sParams[1]).each(function( )
		{
			if (sParams[0] == "Check")
				$(this).prop("checked", true);

			else
				$(this).prop("checked", false);
		});


		if (sParams[1] == "school")
		{
			getClassSectionsList(".school", "#Classes", "", "M");
			getStudentsList(".school", "#ddSession", ".class", "#Students", $("#ddStatus").val( ), "M", "Y");
		}

		else if (sParams[1] == "class")
			getStudentsList(".school", "#ddSession", ".class", "#Students", $("#ddStatus").val( ), "M", "Y");

		return false;
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");
		var bFlag = false;

		$(".school").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false)
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one School.");

			return false;
		}

		if (!objFV.validate("ddSession", "B", "Please select the Session."))
			return false;

		
		var sClasses = "0";

		$(".class").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				sClasses += ("," + $(this).val( ));
		});
		
		
		if (sClasses == "0")
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one Class.");

			return false;
		}



		if (!objFV.validate("txtTitle", "B", "Please enter the Notification Title."))
			return false;
		
		if (!objFV.validate("txtDetails", "B", "Please enter the Notification Details."))
			return false;


		$("#BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});

