	{
		var iNoticeId = this.id;
		var iIndex    = objTable.fnGetPosition($(this).closest('tr')[0]);

		$.colorbox({ href:("students/edit-notice.php?NoticeId=" + iNoticeId + "&Index=" + iIndex), width:"90%", height:"90%", iframe:true, opacity:"0.50", overlayClose:false });

		event.stopPropagation( );
	});


	$(document).on("click", ".icnView", function(event)
	{
		var iNoticeId = this.id;

		$.colorbox({ href:("students/view-notice.php?NoticeId=" + iNoticeId), width:"90%", height:"90%", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});


	$(document).on("click", ".icnToggle", function(event)
	{
		var objIcon = this;
		var objRow  = objTable.fnGetPosition($(this).closest('tr')[0]);

		$(objIcon).removeClass( ).addClass("icon");

		$.post("ajax/students/toggle-notice-status.php",
			{ NoticeId:objIcon.id },

			function (sResponse)
			{
				var sParams = sResponse.split("|-|");

				showMessage("#GridMsg", sParams[0], sParams[1]);


				if (sParams[0] == "success")
				{
					if (objIcon.src.indexOf("success.png") != -1)
						objIcon.src = objIcon.src.replace("success.png", "error.png");

					else
						objIcon.src = objIcon.src.replace("error.png", "success.png");
				}

				$(objIcon).removeClass("icon").addClass("icnToggle");
			},

			"text");

		event.stopPropagation( );
	});


	$(document).on("click", ".icnDelete", function(event)
	{
		var iNoticeId = this.id;
		var objRow    = objTable.fnGetPosition($(this).closest('tr')[0]);

		$("#ConfirmDelete").dialog( { resizable : false,
		                              width     : 420,
		                              height    : 110,
		                              modal     : true,
		                              buttons   : { "Delete" : function( )
		                                                       {
																	$.post("ajax/students/delete-notice.php",
																		{ Notices:iNoticeId },

																		function (sResponse)
																		{
																			var sParams = sResponse.split("|-|");

																			showMessage("#GridMsg", sParams[0], sParams[1]);

																			if (sParams[0] == "success")
																				objTable.fnDeleteRow(objRow);
																		},

																		"text");

		                                                      	    	$(this).dialog("close");
		                                                       },

		                                             Cancel  : function( )
		                                                       {
		                                                            	$(this).dialog("close");
		                                                       }
		                                          }
		                            });

		event.stopPropagation( );
	});






	if ($("#txtNotice").length > 0)
		setupCkEditor("txtNotice");
		
		
	$("#frmRecord #BtnPicture").button({ icons:{ primary:'ui-icon-image' } });
	$("#frmRecord #BtnDocument").button({ icons:{ primary:'ui-icon-document' } }).css("margin-left", "5px");
	$("#frmRecord #BtnVideo").button({ icons:{ primary:'ui-icon-video' } }).css("margin-left", "5px");
	$("#frmRecord #BtnLink").button({ icons:{ primary:'ui-icon-pin-w' } }).css("margin-left", "5px");
	$("#frmRecord .btnRemove").button({ icons:{ primary:'ui-icon-minus' }, text:false });
	
	$("#Attachments .attachment").each(function(iIndex)
	{
		var sType = $(this).attr("rel");
		var sIcon = "ui-icon-pin-w";
	  
		if (sType == "Picture")
			sIcon = "ui-icon-image";
	  
		else if (sType == "Document" || sType == "Video")
			sIcon = ("ui-icon-" + sType.toLowerCase( ));
	  
	  
		$("#frmRecord #btnIcon" + (iIndex + 1)).button({ icons:{ primary:sIcon }, text:false }).attr("disabled", true).css("padding", "6px");
	});

	
	$(document).on("click", "#frmRecord #BtnPicture, #frmRecord #BtnDocument, #frmRecord #BtnVideo, #frmRecord #BtnLink", function( )
	{
	     var sType  = $(this).attr("rel");
		 var iIndex = ($("#Attachments .attachment").length + 1);
		 
		 if (iIndex > 20)
		 {
			 showMessage("#RecordMsg", "info", "You cannot add more Attachment with this Entry.");
			 
			 return false;
		 }


	     $.post("ajax/get-attachment.php",
		    { Index:iIndex, Type:sType },

		    function (sResponse)
		    {
				if ($("#Attachments .attachment").length == 0)
					$("#Attachments").html("");
				
			    
				$("#Attachments").append(sResponse);

			    $("#frmRecord #txtAttachment" + iIndex).focus( );
			    $("#frmRecord .btnRemove").button({ icons:{ primary:'ui-icon-minus' }, text:false });

			  
			    var sIcon = "ui-icon-pin-w";
			  
			    if (sType == "Picture")
				    sIcon = "ui-icon-image";
			  
			    else if (sType == "Document" || sType == "Video")
				    sIcon = ("ui-icon-" + sType.toLowerCase( ));
			  
			  
			    $("#frmRecord #btnIcon" + iIndex).button({ icons:{ primary:sIcon }, text:false }).attr("disabled", true).css("padding", "6px");
		    },

		    "text");


		return false;
	});


	$(document).on("click", "#Attachments .btnRemove", function( )
	{
		var sIndex = $(this).attr("id");
		var sType  = $("#Attachments #Attachment" + sIndex).attr("rel");
		
		if (sType == "Picture" || sType == "Document")
			deleteAttachment($("#Attachments #txtFile" + sIndex).val( ));


		$("#Attachments #Attachment" + sIndex).remove( );

		$("#Attachments .attachment").each(function(iIndex)
		{
			$(this).find(".serial").html((iIndex + 1) + ".");
			$(this).find(".btnIcon").attr("id", (iIndex + 1));
			$(this).find(".title").attr("id", ("txtAttachment" + (iIndex + 1)));
			$(this).find(".title").attr("name", ("txtAttachment" + (iIndex + 1)));
			$(this).find(".picture").attr("id", ("filePicture" + (iIndex + 1)));
			$(this).find(".picture").attr("name", ("filePicture" + (iIndex + 1)));
			$(this).find(".document").attr("id", ("fileDocument" + (iIndex + 1)));
			$(this).find(".document").attr("name", ("fileDocument" + (iIndex + 1)));
			$(this).find(".file").attr("id", ("txtFile" + (iIndex + 1)));
			$(this).find(".file").attr("name", ("txtFile" + (iIndex + 1)));
			$(this).find(".uploadProgress").attr("id", ("UploadProgress" + (iIndex + 1)));
			$(this).find(".video").attr("id", ("txtVideo" + (iIndex + 1)));
			$(this).find(".video").attr("name", ("txtVideo" + (iIndex + 1)));
			$(this).find(".link").attr("id", ("txtLink" + (iIndex + 1)));
			$(this).find(".link").attr("name", ("txtLink" + (iIndex + 1)));
			$(this).find(".btnRemove").attr("id", (iIndex + 1));
			$(this).attr("id", ("Attachment" + (iIndex + 1)));
		});
		
		
		if ($("#Attachments .attachment").length == 0)
			$("#Attachments").html("<p>&bull; No Picture/Document/Video/Link Attached</p>");


		return false;
	});
	
	
	$("#Attachments").sortable(
	{
		update : function (event, ui)
		{
			$("#Attachments .attachment").each(function(iIndex)
			{
				$(this).find(".serial").html((iIndex + 1) + ".");
				$(this).find(".btnIcon").attr("id", (iIndex + 1));
				$(this).find(".title").attr("id", ("txtAttachment" + (iIndex + 1)));
				$(this).find(".title").attr("name", ("txtAttachment" + (iIndex + 1)));
				$(this).find(".picture").attr("id", ("filePicture" + (iIndex + 1)));
				$(this).find(".picture").attr("name", ("filePicture" + (iIndex + 1)));
				$(this).find(".document").attr("id", ("fileDocument" + (iIndex + 1)));
				$(this).find(".document").attr("name", ("fileDocument" + (iIndex + 1)));
				$(this).find(".file").attr("id", ("txtFile" + (iIndex + 1)));
				$(this).find(".file").attr("name", ("txtFile" + (iIndex + 1)));
				$(this).find(".uploadProgress").attr("id", ("UploadProgress" + (iIndex + 1)));
				$(this).find(".video").attr("id", ("txtVideo" + (iIndex + 1)));
				$(this).find(".video").attr("name", ("txtVideo" + (iIndex + 1)));
				$(this).find(".link").attr("id", ("txtLink" + (iIndex + 1)));
				$(this).find(".link").attr("name", ("txtLink" + (iIndex + 1)));
				$(this).find(".btnRemove").attr("id", (iIndex + 1));
				$(this).attr("id", ("Attachment" + (iIndex + 1)));
			});
		}
	});	
	
	
	$(document).on("change", "#Attachments .attachment .picture, #Attachments .attachment .document", function( )
	{
		var sIndex = $(this).parents(".attachment").attr("id").replace("Attachment", "");
		var sType  = "Document";
		
		if ($(this).parents(".attachment").attr("rel") == "Picture")
			sType = "Picture";


		if ((sType == "Picture" && !checkImage(this.files[0].name)) || (sType == "Picture" && !checkDocument(this.files[0].name)))
		{
			showMessage("#RecordMsg", "alert", ("The selected File is not a valid " + sType + ". Please select a valid " + sType + "."));
			
			$(this).val("").focus( );

			return false;
		}


		if (this.files[0].size > (5 * 1024 * 1024))
		{
			showMessage("#RecordMsg", "alert", "The Attachment File Size should be less than 5mb");
			
			$(this).val("").focus( );

			return false;
		}
		
		
		$(this).find(".file").removeClass("hidden");
		$(this).find(".picture").addClass("hidden");
		$(this).find(".document").addClass("hidden");
		
		
		saveAttachment(sIndex, sType, this.files[0])
	});
	
	
	$(document).ajaxStart(function( )
	{
		$("#frmRecord #BtnSave, #frmRecord #BtnReset").attr("disabled", true);
	});


	$(document).ajaxStop(function( )
	{
		$("#frmRecord #BtnSave, #frmRecord #BtnReset").attr("disabled", false);
	});
	
	
	
	$(".school").click(function( )
	{
		getClassSectionsList(".school", "#Classes", "", "M");
		getStudentsList(".school", "#ddSession", ".class", "#Students", $("#ddStatus").val( ), "M");
	});


	$("#ddSession, #ddStatus").change(function( )
	{
		getStudentsList(".school", "#ddSession", ".class", "#Students", $("#ddStatus").val( ), "M");
	});


	$(document).on("click", ".class", function( )
	{
		getStudentsList(".school", "#ddSession", ".class", "#Students", $("#ddStatus").val( ), "M");
	});



	$("#BtnReset").click(function( )
	{
		$("#Attachments .attachment").each(function(iIndex)
		{
			var sType = $(this).attr("rel");
			
			if (sType == "Picture" || sType == "Document")
				deleteAttachment($(this).find(".file").val( ));
		});

		
		$('#frmRecord')[0].reset( );
		$("#RecordMsg").hide( );

		$("#Classes").html("");
		$("#Students").html("");
		$("#Attachments").html("<p>&bull; No Picture/Document/Video/Link Attached</p>");
		
		if (txtNotice)
			txtNotice.setData("");

		return false;
	});


	$("span a").click(function( )
	{
		var sData   = $(this).attr("rel");
		var sParams = sData.split("|");

		$("." + sParams[1]).each(function( )
		{
			if (sParams[0] == "Check")
				$(this).prop("checked", true);

			else
				$(this).prop("checked", false);
		});


		if (sParams[1] == "school")
		{
			getClassSectionsList(".school", "#Classes", "", "M");
			getStudentsList(".school", "#ddSession", ".class", "#Students", $("#ddStatus").val( ), "M");
		}

		else if (sParams[1] == "class")
			getStudentsList(".school", "#ddSession", ".class", "#Students", $("#ddStatus").val( ), "M");

		return false;
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");
		var bFlag = false;

		$(".school").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false)
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one School.");

			return false;
		}

		if (!objFV.validate("ddSession", "B", "Please select the Session."))
			return false;

		var sClasses = "0";

		$(".class").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				sClasses += ("," + $(this).val( ));
		});


		bFlag = false;

		$(".student").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false && sClasses == "0" && objFV.value("txtStudents") == "")
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one Student or enter Registration No.");

			return false;
		}


		if (!objFV.validate("txtTitle", "B", "Please enter the Notice Title."))
			return false;

		if (!objFV.validate("txtNotice", "B", "Please enter the Notice Details."))
			return false;
		
		if (!objFV.validate("txtDate", "B", "Please select the Notice Date."))
			return false;
		
		var objMinNoticeDate = parseDate($("#txtDate").attr("date"));
		var objNoticeDate    = parseDate($("#txtDate").val( ));
		
		if (objNoticeDate.getTime( ) <= objMinNoticeDate.getTime( ))
		{
			showMessage("#RecordMsg", "alert", "You cannot select this Notice Date (Old Dated entries are Restricted).");

			return false;
		}
		
		
		bFlag = false;

		$("#Attachments .attachment").each(function(iIndex)
		{
			var sIndex  = $(this).attr("id").replace("Attachment", "");
			var sType   = $(this).attr("rel");

			if (!objFV.validate(("txtAttachment" + sIndex), "B", ("Please enter the " + sType + " Title # " + (iIndex + 1))))
			{
				bFlag = true;
				return false;
			}

			if (sType == "Picture" && objFV.value(("txtFile" + sIndex)) == "")
			{
				if (!objFV.validate(("filePicture" + sIndex), "B", "Please select a Picture # " + (iIndex + 1)))
				{
					bFlag = true;
					return false;
				}
			}
			
			if (sType == "Document" && objFV.value(("txtFile" + sIndex)) == "")
			{
				if (!objFV.validate(("fileDocument" + sIndex), "B", "Please select a Document # " + (iIndex + 1)))
				{
					bFlag = true;
					return false;
				}
			}

			if (sType == "Video" && !objFV.validate(("txtVideo" + sIndex), "B", "Please enter the Youtube Video Code # " + (iIndex + 1)))
			{
				bFlag = true;
				return false;
			}
			
			if (sType == "Link" && !objFV.validate(("txtLink" + sIndex), "B,U", "Please enter the Download File Link # " + (iIndex + 1)))
			{
				bFlag = true;
				return false;
			}
		});		
		
		if (bFlag == true)
			return false;
		


		bFlag = false;
		
		$("#Attachments .attachment").each(function( )
		{
			var sIndex = $(this).attr("id").replace("Attachment", "");
			var sType  = $(this).attr("rel");

			if (sType == "Picture" || sType == "Document")
			{
				var sFile = $(this).find(".file").val( );
				
				if (sFile == "")
				{
					showMessage("#RecordMsg", "info", ("Please wait, " + sType + " # " + $(this).find(".serial").text( ).replace(".", "") + " is not uploaded yet. Wait till it is uploaded or remove this Attachment."));
				
					bFlag = true;
					return false;
				}
			}
		});
		
		if (bFlag == true)
			return false;		


		$("#BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});


function updateRecord(iNoticeId, iRow, sFields)
{
	$("#DataGrid thead tr th").each(function(iIndex)
	{
		if ($(this).text( ) == "Title")
			objTable.fnUpdate(sFields[0], iRow, iIndex, false);
		
		else if ($(this).text( ) == "Date")
			objTable.fnUpdate(sFields[1], iRow, iIndex, false);

		else if ($(this).text( ) == "Options")
		{
			objTable.fnUpdate(sFields[2], iRow, iIndex, false);

			$(".details").tipTip( );
		}
	});
}

