$(document).ready(function( )
{
	$("#ddStatus").change(function( )
	{
		getEmployeesList(".school", "", ".department", "", "#Employees", $("#ddStatus").val( ), "M");
	});


	$(".school, .department").click(function( )
	{
		getEmployeesList(".school", "", ".department", "", "#Employees", $("#ddStatus").val( ), "M");
	});



	$("#BtnReset").click(function( )
	{
		$('#frmRecord')[0].reset( );
		$("#RecordMsg").hide( );

		$("#Employees").html("");

		return false;
	});


	$("span a").click(function( )
	{
		var sData   = $(this).attr("rel");
		var sParams = sData.split("|");

		$("." + sParams[1]).each(function( )
		{
			if (sParams[0] == "Check")
				$(this).prop("checked", true);

			else
				$(this).prop("checked", false);
		});


		if (sParams[1] == "school" || sParams[1] == "department")
			getEmployeesList(".school", "", ".department", "", "#Employees", $("#ddStatus").val( ), "M");

		return false;
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");
		var bFlag = false;

		$(".school").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false)
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one School.");

			return false;
		}


		var sDepartments = "0";

		$(".department").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				sDepartments += ("," + $(this).val( ));
		});


		bFlag = false;

		$(".employee").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false && sDepartments == "0")
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one Employee or Department.");

			return false;
		}



		if (!objFV.validate("txtTitle", "B", "Please enter the Notification Title."))
			return false;

		if (!objFV.validate("txtDetails", "B", "Please enter the Notification Details."))
			return false;


		$("#BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});

