var objTable;

$(document).ready(function( )
{
	objTable = $("#DataGrid").dataTable( {   sDom            : '<"H"f<"toolbar"><"TableTools">>t<"F"ip>',
											 oLanguage       : { sEmptyTable:"No record found", sInfoEmpty:"0 records", sZeroRecords:"No matching record found" },
											 bJQueryUI       : true,
											 sPaginationType : "full_numbers",
											 bPaginate       : true,
											 bLengthChange   : false,
											 iDisplayLength  : parseInt($("#RecordsPerPage").val( )),
											 bFilter         : true,
											 bSort           : true,
											 aoColumnDefs    : [ { asSorting:["asc"], aTargets:[0] }, { bSortable:false, aTargets:[9] } ],
											 bInfo           : true,
											 bStateSave      : false,
											 bProcessing     : false,
											 bAutoWidth      : false,
											 fnDrawCallback  : function( ) { setTimeout(function( ) { initTableSorting("#DataGrid", "#GridMsg", objTable); }, 0); }
										   } );


	$(".TableTools").prepend('<button id="BtnMultiDelete">Delete Selected Rows</button>');
	$("#BtnMultiDelete").button({ icons:{ primary:'ui-icon-trash' } });
	$("#BtnMultiDelete").hide( );


	$(document).on("click", "#DataGrid tr", function( )
	{
		if ($(this).find("img.icnDelete").length == 0)
			return false;


		if ($(this).hasClass("selected"))
			$(this).removeClass("selected");

		else
			$(this).addClass("selected");


		var bSelected = false;
		var objRows   = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if ($(objRows[i]).hasClass("selected"))
			{
				bSelected = true

				break;
			}
		}

		if (bSelected == true)
			$("#BtnMultiDelete").show( );

		else
			$("#BtnMultiDelete").hide( );
	});


	$(document).on("click", "#BtnMultiDelete", function( )
	{
		var sTypes          = "";
		var objSelectedRows = new Array( );

		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if ($(objRows[i]).hasClass("selected"))
			{
				if (sTypes != "")
					sTypes += ",";

				sTypes += objRows[i].id;

				objSelectedRows.push(objRows[i]);
			}
		}

		if (sTypes != "")
		{
			$("#ConfirmMultiDelete").dialog( {  resizable : false,
												width     : 420,
												height    : 110,
												modal     : true,
												buttons   : { "Delete" : function( )
																		{
																			 $.post("ajax/hr/delete-leave-type.php",
																				{ Types:sTypes },

																				function (sResponse)
																				{
																					var sParams = sResponse.split("|-|");

																					showMessage("#GridMsg", sParams[0], sParams[1]);

																					if (sParams[0] == "success")
																					{
																						 for (var i = 0; i < objSelectedRows.length; i ++)
																							  objTable.fnDeleteRow(objSelectedRows[i]);

																						  $("#BtnMultiDelete").hide( );
																					}
																				},

																				"text");

																			$(this).dialog("close");
																		},

															  Cancel  : function( )
																		{
																			$(this).dialog("close");
																		}
													   }
											  });
		}
	});


	$(document).on("click", "#DataGrid .icnToggle", function(event)
	{
		var objIcon = this;
		var objRow  = objTable.fnGetPosition($(this).closest('tr')[0]);

		$(objIcon).removeClass( ).addClass("icon");

		$.post("ajax/hr/toggle-leave-type-status.php",
			{ TypeId:objIcon.id },

			function (sResponse)
			{
				var sParams = sResponse.split("|-|");

				showMessage("#GridMsg", sParams[0], sParams[1]);


				if (sParams[0] == "success")
				{
					var iColumn = 0;

					$("#DataGrid thead tr th").each(function(iIndex)
					{
						if ($(this).text( ) == "Status")
							iColumn = iIndex;
					});


					if (objIcon.src.indexOf("success.png") != -1)
					{
						objIcon.src = objIcon.src.replace("success.png", "error.png");

						objTable.fnUpdate("In-Active", objRow, iColumn, false);
					}

					else
					{
						objIcon.src = objIcon.src.replace("error.png", "success.png");

						objTable.fnUpdate("Active", objRow, iColumn, false);
					}
				}

				$(objIcon).removeClass("icon").addClass("icnToggle");
			},

			"text");

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnEdit", function(event)
	{
		var iTypeId = this.id;
		var iIndex  = objTable.fnGetPosition($(this).closest('tr')[0]);

		$.colorbox({ href:("hr/edit-leave-type.php?TypeId=" + iTypeId + "&Index=" + iIndex), width:"850px", height:"650px", iframe:true, opacity:"0.50", overlayClose:false });

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnView", function(event)
	{
		var iTypeId = this.id;

		$.colorbox({ href:("hr/view-leave-type.php?TypeId=" + iTypeId), width:"850px", height:"600px", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnDelete", function(event)
	{
		var iTypeId = this.id;
		var objRow  = objTable.fnGetPosition($(this).closest('tr')[0]);

		$("#ConfirmDelete").dialog( { resizable : false,
									  width     : 420,
									  height    : 110,
									  modal     : true,
									  buttons   : { "Delete" : function( )
															   {
																	$.post("ajax/hr/delete-leave-type.php",
																		{ Types:iTypeId },

																		function (sResponse)
																		{
																			var sParams = sResponse.split("|-|");

																			showMessage("#GridMsg", sParams[0], sParams[1]);

																			if (sParams[0] == "success")
																				objTable.fnDeleteRow(objRow);
																		},

																		"text");

																	$(this).dialog("close");
															   },

													 Cancel  : function( )
															   {
																	$(this).dialog("close");
															   }
												  }
									});

		event.stopPropagation( );
	});




	$("#frmRecord #BtnReset").click(function( )
	{
		$("#frmRecord")[0].reset( );
		$("#RecordMsg").hide( );
		$("#frmRecord #txtType").focus( );

		return false;
	});


	$("#frmRecord #txtType").blur(function( )
	{
		if ($(this).val( ) == "")
			return;

		$.post("ajax/hr/check-leave-type.php",
			{ Type:$(this).val( ) },

			function (sResponse)
			{
				if (sResponse == "USED")
				{
					showMessage("#RecordMsg", "info", "The specified Leave Type already exists in the System.");

					$("#DuplicateType").val("1");
				}

				else
				{
					$("#RecordMsg").hide( );
					$("#DuplicateType").val("0");
				}
			},

			"text");
	});


	$("#txtMinimum").mask("9?99");
	$("#txtMaximum").mask("9?99");


	$("#frmRecord #ddWeightage").change(function( )
	{
		if ($(this).val( ) != "1")
			$("#MergeInCl").show("blind");

		else
		{
			$("#MergeInCl").hide("blind");
			$("#ddClMerge").val("N");
		}
	});


	$("#frmRecord #ddNoOfRequests").change(function( )
	{
		if (parseInt($(this).val( )) > 1)
			$("#Gap").show("blind");

		else
		{
			$("#Gap").hide("blind");
			$("#ddGapYears").val("0");
			$("#ddGapMonths").val("0");
		}
	});	


	$("#frmRecord #ddCarryForward").change(function( )
	{
		if ($(this).val( ) == "Y")
			$("#CarryForward").show("blind");

		else
			$("#CarryForward").hide("blind");
	});	


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");

		if (!objFV.validate("txtType", "B", "Please enter the Leave Type."))
			return false;


		var bFlag = false;

		$(".gender").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false)
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one Gender.");

			return false;
		}


		bFlag = false;

		$(".maritalStatus").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false)
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one Marital Status.");

			return false;
		}


		bFlag = false;

		$(".jobType").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false)
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one Job Type.");

			return false;
		}


		if (!objFV.validate("txtMinimum", "B,N", "Please select the Minimum Leave Days."))
			return false;

		if (parseInt(objFV.value("txtMinimum")) <= 0)
		{
			showMessage("#RecordMsg", "alert", "Please select a valid Minimum Leave Days Limit.");

			objFV.focus("txtMinimum");
			objFV.select("txtMinimum");

			return false;
		}

		if (parseInt(objFV.value("txtMaximum")) > 0 && parseInt(objFV.value("txtMaximum")) < parseInt(objFV.value("txtMinimum")))
		{
			showMessage("#RecordMsg", "alert", "Please select a valid Maximum Leave Days Limit.");

			objFV.focus("txtMaximum");
			objFV.select("txtMaximum");

			return false;
		}

		if (parseInt(objFV.value("ddNoOfRequests")) > 0 && objFV.value("ddCarryForward") == "Y")
		{
			showMessage("#RecordMsg", "alert", "This Leave Type cannot be Carry Forwarded.");

			objFV.focus("ddCarryForward");
			objFV.select("ddCarryForward");

			return false;
		}

		if (parseInt(objFV.value("ddNoOfRequests")) > 0 && objFV.value("ddddProrated") == "Y")
		{
			showMessage("#RecordMsg", "alert", "This Leave Type cannot be Prorated.");

			objFV.focus("ddProrated");
			objFV.select("ddProrated");

			return false;
		}

		if (objFV.value("DuplicateType") == "1")
		{
			showMessage("#RecordMsg", "info", "The specified Leave Type already exists in the System.");

			objFV.focus("txtType");
			objFV.select("txtType");

			return false;
		}


		$("#frmRecord #BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});


function updateRecord(iTypeId, iRow, sFields)
{
	$("#DataGrid thead tr th").each(function(iIndex)
	{
		if ($(this).text( ) == "Leave Type")
			objTable.fnUpdate(sFields[0], iRow, iIndex, false);

		else if ($(this).text( ) == "Gender")
			objTable.fnUpdate(sFields[1], iRow, iIndex, false);

		else if ($(this).text( ) == "Minimum")
			objTable.fnUpdate(sFields[2], iRow, iIndex, false);

		else if ($(this).text( ) == "Maximum")
			objTable.fnUpdate(sFields[3], iRow, iIndex, false);

		else if ($(this).text( ) == "Service Length")
			objTable.fnUpdate(sFields[4], iRow, iIndex, false);

		else if ($(this).text( ) == "No of Requests")
			objTable.fnUpdate(sFields[5], iRow, iIndex, false);

		else if ($(this).text( ) == "Carry Forward")
			objTable.fnUpdate(sFields[6], iRow, iIndex, false);

		else if ($(this).text( ) == "Prorated")
			objTable.fnUpdate(sFields[7], iRow, iIndex, false);
	});


	$("#DataGrid .icnToggle").each(function(iIndex)
	{
		if ($(this).attr("id") == iTypeId)
			$(this).attr("src", sFields[8]);
	});
}

