		if ($(this).parents(".attachment").attr("rel") == "Picture")
			sType = "Picture";


		if ((sType == "Picture" && !checkImage(this.files[0].name)) || (sType == "Picture" && !checkDocument(this.files[0].name)))
		{
			showMessage("#RecordMsg", "alert", ("The selected File is not a valid " + sType + ". Please select a valid " + sType + "."));

			$(this).val("").focus( );

			return false;
		}


		if (this.files[0].size > (5 * 1024 * 1024))
		{
			showMessage("#RecordMsg", "alert", "The Attachment File Size should be less than 5mb");

			$(this).val("").focus( );

			return false;
		}


		$(this).find(".file").removeClass("hidden");
		$(this).find(".picture").addClass("hidden");
		$(this).find(".document").addClass("hidden");


		saveAttachment(sIndex, sType, this.files[0])
