	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");

		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;

		if (!objFV.validate("ddClass", "B", "Please select the Class."))
			return false;


		var bSections = false;

		$(".section").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bSections = true;
		});

		if (bSections == false)
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one Section.");

			return false;
		}


		if (!objFV.validate("ddSubject", "B", "Please select the Subject."))
			return false;

		if (!objFV.validate("ddType", "B", "Please select the Homework Type."))
			return false;

		if (!objFV.validate("txtDate", "B", "Please select the Homework Date."))
			return false;

		if (objFV.value("ddType") == "2")
		{
			if (!objFV.validate("txtDueDateTime", "B", "Please select the Homework Due Date/Time."))
				return false;
		}

		if (!objFV.validate("txtTopic", "B", "Please enter the Topic."))
			return false;

		if (!objFV.validate("txtDetails", "B", "Please enter the Homework Details."))
			return false;


		var bFlag = false;

		$("#Attachments .attachment").each(function(iIndex)
		{
			var sIndex  = $(this).attr("id").replace("Attachment", "");
			var sType   = $(this).attr("rel");

			if (!objFV.validate(("txtAttachment" + sIndex), "B", ("Please enter the " + sType + " Title # " + (iIndex + 1))))
			{
				bFlag = true;
				return false;
			}

			if (sType == "Picture" && objFV.value(("txtFile" + sIndex)) == "")
			{
				if (!objFV.validate(("filePicture" + sIndex), "B", "Please select a Picture # " + (iIndex + 1)))
				{
					bFlag = true;
					return false;
				}
			}

			if (sType == "Document" && objFV.value(("txtFile" + sIndex)) == "")
			{
				if (!objFV.validate(("fileDocument" + sIndex), "B", "Please select a Document # " + (iIndex + 1)))
				{
					bFlag = true;
					return false;
				}
			}

			if (sType == "Video" && !objFV.validate(("txtVideo" + sIndex), "B", "Please enter the Youtube Video Code # " + (iIndex + 1)))
			{
				bFlag = true;
				return false;
			}

			if (sType == "Link" && !objFV.validate(("txtLink" + sIndex), "B,U", "Please enter the Download File Link # " + (iIndex + 1)))
			{
				bFlag = true;
				return false;
			}
		});		

		if (bFlag == true)
			return false;



		bFlag = false;

		$("#Attachments .attachment").each(function( )
		{
			var sIndex = $(this).attr("id").replace("Attachment", "");
			var sType  = $(this).attr("rel");

			if (sType == "Picture" || sType == "Document")
			{
				var sFile = $(this).find(".file").val( );

				if (sFile == "")
				{
					showMessage("#RecordMsg", "info", ("Please wait, " + sType + " # " + $(this).find(".serial").text( ).replace(".", "") + " is not uploaded yet. Wait till it is uploaded or remove this Attachment."));

					bFlag = true;
					return false;
				}
			}
		});

		if (bFlag == true)
			return false;	



		if (objFV.value("DuplicateHomework") == "1")
		{
			showMessage("#RecordMsg", "info", "The Homework for selected School/Class/Section/Subject/Type/Date has already been entered.");

			objFV.focus("ddSchool");
			objFV.select("ddSchool");

			return false;
		}		


		$("#BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});


function updateRecord(iHomeworkId, iRow, sFields)
{
	if (parseInt($("#TotalRecords").val( )) <= 100)
	{
		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "School")
				objTable.fnUpdate(sFields[0], iRow, iIndex, false);

			else if ($(this).text( ) == "Class")
				objTable.fnUpdate(sFields[1], iRow, iIndex, false);

			else if ($(this).text( ) == "Sections")
				objTable.fnUpdate(sFields[2], iRow, iIndex, false);

			else if ($(this).text( ) == "Subject")
				objTable.fnUpdate(sFields[3], iRow, iIndex, false);

			else if ($(this).text( ) == "Type")
				objTable.fnUpdate(sFields[4], iRow, iIndex, false);

			else if ($(this).text( ) == "Topic")
				objTable.fnUpdate(sFields[5], iRow, iIndex, false);

			else if ($(this).text( ) == "Date")
				objTable.fnUpdate(sFields[6], iRow, iIndex, false);

			else if ($(this).text( ) == "Options")
				objTable.fnUpdate(sFields[7], iRow, iIndex, false);
		});


		$(".details").tipTip( );
	}

	else
		objTable.fnStandingRedraw( );
}

