			var objRows   = objTable.fnGetNodes( );
			var bSelected = false;


			for (var i = 0; i < objRows.length; i ++)
			{
				if ($(objRows[i]).find("img.icnDelete").length == 0)
				{
					$(objRows[i]).removeClass("selected");

					continue;
				}


				if (!$(objRows[i]).hasClass("selected"))
				{
					$(objRows[i]).addClass("selected");

					bSelected = true;
				}
			}


			if (bSelected == true)
				$("#BtnMultiDelete").show( );
		});


		$("#BtnSelectNone").click(function( )
		{
			var objRows = objTable.fnGetNodes( );

			for (var i = 0; i < objRows.length; i ++)
				$(objRows[i]).removeClass("selected");

			$("#BtnMultiDelete").hide( );
		});


		$(document).on("click", "#DataGrid tr", function( )
		{
			if ($(this).find("img.icnDelete").length == 0)
				return false;


			if ($(this).hasClass("selected"))
				$(this).removeClass("selected");

			else
				$(this).addClass("selected");


			var bSelected = false;
			var objRows   = objTable.fnGetNodes( );

			for (var i = 0; i < objRows.length; i ++)
			{
				if ($(objRows[i]).hasClass("selected"))
				{
					bSelected = true;

					break;
				}
			}


			if (bSelected == true)
				$("#BtnMultiDelete").show( );

			else
				$("#BtnMultiDelete").hide( );
		});


		$(".TableTools").prepend('<button id="BtnMultiDelete">Delete Selected Rows</button>');
		$("#BtnMultiDelete").button({ icons:{ primary:'ui-icon-trash' } });
		$("#BtnMultiDelete").hide( );


		$(document).on("click", "#BtnMultiDelete", function( )
		{
			var sFee            = "";
			var objSelectedRows = new Array( );

			var objRows = objTable.fnGetNodes( );

			for (var i = 0; i < objRows.length; i ++)
			{
				if ($(objRows[i]).hasClass("selected"))
				{
					if (sFee != "")
						sFee += ",";

					sFee += objRows[i].id;

					objSelectedRows.push(objRows[i]);
				}
			}

			if (sFee != "")
			{
				$("#ConfirmMultiDelete").dialog( { resizable : false,
												   width     : 420,
												   height    : 110,
												   modal     : true,
												   buttons   : { "Delete" : function( )
																		   {
																				 $.post("ajax/billing/delete-fee.php",
																					{ Fee:sFee },

																					function (sResponse)
																					{
																						var sParams = sResponse.split("|-|");

																						showMessage("#GridMsg", sParams[0], sParams[1]);

																						if (sParams[0] == "success")
																						{
																							 for (var i = 0; i < objSelectedRows.length; i ++)
																								  objTable.fnDeleteRow(objSelectedRows[i]);

																							  $("#BtnMultiDelete").hide( );


																							  if ($("#SelectButtons").length == 1)
																							  {
																									if (objTable.fnGetNodes( ).length > 1 && $("#DataGrid .icnDelete").length > 0)
																										$("#SelectButtons").show( );

																									else
																										$("#SelectButtons").hide( );
																							  }
																						}
																					},

																					"text");

																				$(this).dialog("close");
																		   },

																 Cancel  : function( )
																		   {
																				$(this).dialog("close");
																		   }
															   }
												 });
			}
		});


		$(document).on("click", "#DataGrid .icnEdit", function(event)
		{
			var iFeeId = this.id;
			var iIndex = objTable.fnGetPosition($(this).closest('tr')[0]);

			$.colorbox({ href:("billing/edit-fee.php?FeeId=" + iFeeId + "&Index=" + iIndex), width:"90%", maxWidth:"1200px", height:"90%", maxHeight:"600px", iframe:true, opacity:"0.50", overlayClose:false });

			event.stopPropagation( );
		});


		$(document).on("click", "#DataGrid .icnDueDate", function(event)
		{
			var iFeeId = this.id;
			var iIndex = objTable.fnGetPosition($(this).closest('tr')[0]);

			$.colorbox({ href:("billing/edit-fee-due-date.php?FeeId=" + iFeeId + "&Index=" + iIndex), width:"90%", maxWidth:"1100px", height:"90%", maxHeight:"500px", iframe:true, opacity:"0.50", overlayClose:false });

			event.stopPropagation( );
		});


		$(document).on("click", "#DataGrid .icnView", function(event)
		{
			var iFeeId = this.id;

			$.colorbox({ href:("billing/view-fee.php?FeeId=" + iFeeId), width:"900px", height:"520px", iframe:true, opacity:"0.50", overlayClose:true });

			event.stopPropagation( );
		});


		$(document).on("click", "#DataGrid .icnDelete", function(event)
		{
			var iFeeId = this.id;
			var objRow = objTable.fnGetPosition($(this).closest('tr')[0]);

			$("#ConfirmDelete").dialog( { resizable : false,
										  width     : 420,
										  height    : 110,
										  modal     : true,
										  buttons   : { "Delete" : function( )
																   {
																		$.post("ajax/billing/delete-fee.php",
																			{ Fee:iFeeId },

																			function (sResponse)
																			{
																				var sParams = sResponse.split("|-|");

																				showMessage("#GridMsg", sParams[0], sParams[1]);

																				if (sParams[0] == "success")
																					objTable.fnDeleteRow(objRow);
																			},

																			"text");

																		$(this).dialog("close");
																   },

														 Cancel  : function( )
																   {
																		$(this).dialog("close");
																   }
											  }
									 });

			event.stopPropagation( );
		});


		$(document).on("click", ".icnPrint", function(event)
		{
			var iFeeId = this.id;


			$.post("ajax/billing/print-fee-receipt.php",
				{ FeeId:iFeeId },

				function (sResponse)
				{
					var sParams = sResponse.split("|-|");

					showMessage("#GridMsg", sParams[0], sParams[1]);
				},

				"text");


			event.stopPropagation( );
		});			


		$("#BtnExport").click(function( )
		{
			$("#BtnExport").attr("disabled", true);


			setTimeout(function( )
			{
				$("#BtnExport").attr("disabled", false);
			},

			10000);


			$("#frmExport").trigger("submit");

			return false;
		});



		if ($("#DueDatesArea").length == 1)
		{
			if ($("#frmExport").length == 0)
				$("#DueDatesArea").hide( );

			$("#frmDueDates #BtnSave").button({ icons:{ primary:'ui-icon-disk' } });

			$("#frmDueDates #txtDueDate").datepicker(
			{
				showOn          : "both",
				buttonImage     : "images/icons/calendar.gif",
				buttonImageOnly : true,
				dateFormat      : "yy-mm-dd",
				minDate         :  parseDate($("#frmDueDates #txtDueDate").attr("date"), true),
				maxDate         : "90"
			});


			if ($("#frmDueDates #txtDueDate").prop("disabled") == true)
				$("#frmDueDates #txtDueDate").datepicker('option', 'disabled', true);


			$("#frmDueDates #BtnSave").click(function( )
			{
				var objFV  = new FormValidator("frmDueDates", "DueDatesMsg");

				if (!objFV.validate("txtDueDate", "B", "Please select the Due Date."))
					return false;


				$("#ConfirmDueDate").dialog( {  resizable : false,
												width     : 440,
												height    : 110,
												modal     : true,
												buttons   : { "Update" : function( )
																		{
																			$(this).dialog("close");

																			$("body").append('<div id="Overlay"></div>');
																			$("#Overlay").addClass("ui-widget-overlay");
																			$("#Overlay").css({ width:($(window).width( ) + "px"), height:($(window).height( ) + "px"), zIndex:99999999 });

																			$("#frmDueDates #BtnSave").attr('disabled', true);
																			$("#frmDueDates").trigger("submit");																			
																		},

															Cancel  : function( )
																		{
																			$(this).dialog("close");
																		}
													}
										});


				return false;
			});


			$("#frmDueDates").submit(function( )
			{
				return true;
			});
		}


		if ($("#FeeBillsArea").length == 1)
		{
			if ($("#frmExport").length == 0)
				$("#FeeBillsArea").hide( );


			$("#frmFeeBills #BtnSave").button({ icons:{ primary:'ui-icon-disk' } });
			$("#frmFeeBills #BtnAdd").button({ icons:{ primary:'ui-icon-plusthick' },  text:false });
			$("#frmFeeBills .btnRemove").button({ icons:{ primary:'ui-icon-minus' },  text:false });


			$(document).on("change", "#frmFeeBills select.category", function( )
			{
				var iIndex = $(this).attr("name").replace("ddFeeCategory", "");

				if ($(this).val( ) == "Other")
				{
					$(this).replaceWith($("<input/>", {"type":"text", "name":("txtFeeCategory" + iIndex), "id":("txtFeeCategory" + iIndex), "class":"textbox category", "maxlength":"100", "spellcheck":"true", "style":"width:95%" }));
					$("#txtFeeCategory" + iIndex).focus( );
				}
			});


			$(document).on("keyup", "#frmFeeBills input.category", function(e)
			{
				if ($(this).val( ) == "" && e.keyCode == 8)
				{
					var iIndex = $(this).attr("name").replace("txtFeeCategory", "");

					$(this).parent( ).html($("#FeeCategory select").parent( ).html( ).replaceAll("[Index]", iIndex));
					$("#ddFeeCategory" + iIndex).focus( );
				}
			});


			$("#frmFeeBills #BtnAdd").click(function( )
			{
				var iCount = parseInt($("#frmFeeBills #Count").val( ));

				$("#frmFeeBills #FeeCategories").append($("#FeeCategory").html( ).replaceAll("[Index]", iCount));
				$("#frmFeeBills .btnRemove").button({ icons:{ primary:'ui-icon-minus' },  text:false });
				$("#frmFeeBills #FeeCategory" + iCount).show("blind");

				setTimeout(function( )
				{
					$("#frmFeeBills .feeCategory").each(function(iIndex)
					{
						$(this).find("tr").removeClass( ).addClass((((iIndex % 2) == 0) ? 'even' : 'odd'));
					});	
				}, 300);


				$("#frmFeeBills #Count").val(iCount + 1);

				return false;
			});


			$(document).on("click", "#frmFeeBills .btnRemove", function( )
			{
				var iIndex = $(this).attr("id");

				$("#frmFeeBills #FeeCategories #FeeCategory" + iIndex).hide("blind");


				setTimeout(function( )
				{
					$("#frmFeeBills #FeeCategories #FeeCategory" + iIndex).remove( );
					$("#frmFeeBills #Count").val(parseInt($("#FeeCategories .feeCategory").length));


					$("#frmFeeBills #FeeCategories .feeCategory").each(function(iIndex)
					{
						$(this).attr("id", ("FeeCategory" + iIndex));
						$(this).find("select.category").attr("id", ("ddFeeCategory" + iIndex));
						$(this).find("select.category").attr("name", ("ddFeeCategory" + iIndex));
						$(this).find("input.category").attr("id", ("txtFeeCategory" + iIndex));
						$(this).find("input.category").attr("name", ("txtFeeCategory" + iIndex));
						$(this).find("select.action").attr("id", ("ddFeeAction" + iIndex));
						$(this).find("select.action").attr("name", ("ddFeeAction" + iIndex));
						$(this).find(".amount").attr("id", ("txtFeeAmount" + iIndex));
						$(this).find(".amount").attr("name", ("txtFeeAmount" + iIndex));

						if (iIndex > 0)
							$(this).find(".btnRemove").attr("id", iIndex);
					});


					setTimeout(function( )
					{
						$("#frmFeeBills #FeeCategories .feeCategory").each(function(iIndex)
						{
							$(this).find("tr").removeClass( ).addClass((((iIndex % 2) == 0) ? 'even' : 'odd'));
						});

					}, 300);

				}, 300);


				return false;
			});


			$("#frmFeeBills").submit(function( )
			{
				var objFV  = new FormValidator("frmFeeBills", "FeeBillsMsg");
				var iCount = parseInt($("#frmFeeBills #Count").val( ));
				var bFlag  = true;


				for (var i = 0; i < iCount; i ++)
				{
					if ($("#ddFeeCategory" + i).length == 1)
					{
						if (!objFV.validate(("ddFeeCategory" + i), "B", "Please select the Fee Category."))
						{
							bFlag = false;

							return false;
						}
					}

					else if (!objFV.validate(("txtFeeCategory" + i), "B", "Please enter the Fee Category."))
					{
						bFlag = false;

						return false;
					}

					if (!objFV.validate(("txtFeeAmount" + i), "B,N,S", "Please enter the Fee Amount."))
					{
						bFlag = false;

						return false;
					}
				}


				if (bFlag == false)
					return false;



				$("#frmFeeBills #FeeBillsMsg").hide( );


				$("#ConfirmFeeBills").dialog( { resizable : false,
												width     : 440,
												height    : 110,
												modal     : true,
												buttons   : { "Update" : function( )
																		{
																			$(this).dialog("close");

																			$("body").append('<div id="Overlay"></div>');
																			$("#Overlay").addClass("ui-widget-overlay");
																			$("#Overlay").css({ width:($(window).width( ) + "px"), height:($(window).height( ) + "px"), zIndex:99999999 });

																			$("#frmFeeBills #BtnSave, #frmFeeBills #BtnAdd").attr('disabled', true);
																			$("#frmFeeBills")[0].submit( );
																		},

															Cancel  : function( )
																		{
																			$(this).dialog("close");
																		}
													}
				});


				return false;
			});
		}
	}
});


function updateRecord(iFeeId, iRow, sFields)
{
	$("#DataGrid thead tr th").each(function(iIndex)
	{
		if ($(this).text( ) == "Amount")
			objTable.fnUpdate(sFields[0], iRow, iIndex, false);

		else if ($(this).text( ) == "Due Date")
			objTable.fnUpdate(sFields[1], iRow, iIndex, false);

		else if ($(this).text( ) == "Paid")
			objTable.fnUpdate(sFields[2], iRow, iIndex, false);		
	});


	$("#DataGrid .details").each(function(iIndex)
	{
		if ($(this).attr("id") == iFeeId)
			$(this).attr("title", sFields[3]);
	});

	$(".details").tipTip( );
}

