$(document).ready(function( )
{
	$("#txtPaidDate").datepicker(
	{
		showOn           :  "both",
		buttonImage      :  "images/icons/calendar.gif",
		buttonImageOnly  :  true,
		dateFormat       :  "yy-mm-dd",
		maxDate          :  "0",
		minDate          :  parseDate($("#txtPaidDate").attr("date"), true)
	});
	
	
	$("#txtPaidDate").change(function( )
	{
		var sPaidDate  = $(this).val( ).split("-");
		var sDueDate   = $(this).attr("dueDate").split("-");
		
		var dPaidDate  = new Date(sPaidDate[0], (sPaidDate[1] - 1), sPaidDate[2]);
		var dDueDate   = new Date(sDueDate[0], (sDueDate[1] - 1), sDueDate[2]);
    	var iDays      = ((dPaidDate - dDueDate) / (1000 * 60 * 60 * 24));
		
		if (iDays < 0)
			iDays = 0;
		
		
		var iPerDayFine    = parseInt($("#txtFine").attr("fine"));
		var iMaxFine       = parseInt($("#txtFine").attr("maxFine"));
		var iNetTotal      = parseInt($("#TdNetTotal").attr("voucherAmount"));
		var iNetConcession = parseInt($("#TdNetConcession").attr("concession"));


		if (isNaN(iPerDayFine))
			iPerDayFine = 0;

		if (isNaN(iMaxFine))
			iMaxFine = 0;
		
		if (isNaN(iNetTotal))
			iNetTotal = 0;
		
		if (isNaN(iNetConcession))
			iNetConcession = 0;


		var iFine = (iDays * iPerDayFine);

		if (iFine > iMaxFine && iMaxFine > 0)
			iFine = iMaxFine;
		

		if (iDays > 0)
			$("#txtFine").val(iFine);
		
		else
			$("#txtFine").val("0");
		

		iNetTotal -= iNetConcession;
		
		
		$(".tdPrevFee").each(function( )
		{
			var iPrevAmount  = parseInt($(this).attr("amount"));		
			var sPrevDueDate = $(this).attr("dueDate").split("-");
			var dPrevDueDate = new Date(sPrevDueDate[0], (sPrevDueDate[1] - 1), sPrevDueDate[2]);			
			var iDays        = ((dPaidDate - dPrevDueDate) / (1000 * 60 * 60 * 24));
			
			if (iDays < 0)
				iDays = 0;


			var iPrevFine = (iDays * iPerDayFine);		

			if (iPrevFine > iMaxFine && iMaxFine > 0)
				iPrevFine = iMaxFine;
			
			
			iNetTotal += iPrevAmount;
			iNetTotal += iPrevFine;
			
			$(this).html((iPrevAmount + iPrevFine).formatNumber( ));
			$(this).parent( ).find(".tdPrevAmount").html((iPrevAmount + iPrevFine).formatNumber( ));
		});
		

		$("#TdNetTotal").html(iNetTotal.formatNumber( ));
		$("#NetTotal").val(iNetTotal);
		$("#AmountDue span").html((iNetTotal + iFine).formatNumber( ));
		
		$("#txtPaidAmount").val((iNetTotal + iFine));
		$("#txtPaidAmount").trigger("blur");
	});
	
	
	$("#txtFine").blur(function( ) 
	{
		var iFine       = parseInt($("#txtFine").val( ));
		var iMaxFine    = parseInt($("#txtFine").attr("maxFine"));
		var iNetTotal   = parseInt($("#NetTotal").val( ));
		var iPaidAmount = parseInt($("#txtPaidAmount").val( ));


		if (isNaN(iPaidAmount))
			iPaidAmount = 0;

		if (isNaN(iFine))
			iFine = 0;

		if (isNaN(iMaxFine))
			iMaxFine = 0;
		
		if (isNaN(iNetTotal))
			iNetTotal = 0;
		

		if (iFine > iMaxFine && iMaxFine > 0)
			iFine = iMaxFine;

		
		$("#txtFine").val(iFine);
		$("#AmountDue span").html((iNetTotal + iFine).formatNumber( ));

		$("#txtPaidAmount").trigger("blur");
	});


	$("#ddPaymentMode").change(function( )
	{
		if ($(this).val( ) == "BC" || $(this).val( ) == "BT" || $(this).val( ) == "CH")
		{
			if ($("#BankAccount").css('display') == "none")
				$("#BankAccount").show('blind');
			
			if ($(this).val( ) == "CH")
			{
				if ($("#Cheque").css('display') == "none")
					$("#Cheque").show('blind');
			}
		}

		else
		{
			if ($("#BankAccount").css('display') == "block")
				$("#BankAccount").hide( );
		}
		
		
		if ($(this).val( ) != "CH")
		{
			if ($("#Cheque").css('display') == "block")
				$("#Cheque").hide("blind");
		}
	});
	
	
	$("#ddPaymentMode").trigger("change");
	
	
	$("#txtPaidAmount").blur(function( )
	{
		var iNetTotal         = parseInt($("#NetTotal").val( ));
		var iPaidAmount       = parseInt($("#txtPaidAmount").val( ));
		var iFine             = parseInt($("#txtFine").val( ));
		var sAcceptPartialFee = $(this).attr("acceptPartialFee");


		if (isNaN(iNetTotal))
			iNetTotal = 0;

		if (isNaN(iPaidAmount))
			iPaidAmount = 0;
		
		if (isNaN(iFine))
			iFine = 0;
		
		
		iNetTotal += iFine;
		
		if (sAcceptPartialFee != "Y")
		{
			iPaidAmount  = parseInt($("#txtPaidAmount").attr("amount"));			
			iPaidAmount += iFine;
			
			$("#txtPaidAmount").val(iPaidAmount);
			
			return;
		}
		
		
		if (iPaidAmount > 0)
		{
			if ($("#ReceivedPayment").css("display") != "block")
				$("#ReceivedPayment").show("blind");
			
			$("#AmountReceived span").html(iPaidAmount.formatNumber( ));
		}
			
		else
		{
			if ($("#ReceivedPayment").css("display") == "block")
				$("#ReceivedPayment").hide("blind");
		}
		
		
		if (iPaidAmount > 0 && iPaidAmount < iNetTotal)
		{
			if ($("#ShortPayment").css("display") != "block")
				$("#ShortPayment").show("blind");
			
			$("#RemainingPayment span").html((iNetTotal - iPaidAmount).formatNumber( ));
		}
			
		else
		{
			if ($("#ShortPayment").css("display") == "block")
				$("#ShortPayment").hide("blind");
		}
	});
	


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");


		if (!objFV.validate("txtPaidDate", "B", "Please select the Paid Date."))
			return false;
		
		
		var objMinDate = parseDate($("#txtPaidDate").attr("date"));
		var objDate    = parseDate($("#txtPaidDate").val( ));
		
		if (objDate.getTime( ) <= objMinDate.getTime( ))
		{
			showMessage("#RecordMsg", "alert", "You cannot select this Paid Date (Old Dated entries are Restricted).");

			return false;
		}


		var iNetTotal   = parseInt($("#NetTotal").val( ));
		var iFine       = parseInt($("#txtFine").val( ));
		var iPaidAmount = parseInt($("#txtPaidAmount").val( ));
		
		if (isNaN(iPaidAmount))
			iPaidAmount = 0;
		
		if (isNaN(iFine))
			iFine = 0;

		
		if (!objFV.validate("txtPaidAmount", "B,N", "Please enter the valid Amount Collected."))
			return false;
		
		if (parseInt($("#txtPaidAmount")) < 0)
		{
			showMessage("#RecordMsg", "alert", "Please enter the valid Amount Collected.");
			
			$("#txtPaidAmount").focus( );
			
			return false;
		}
		
		if (iPaidAmount >  (iNetTotal + iFine))
		{
			showMessage("#RecordMsg", "alert", "Amount Collected can't not greater then the Total Due Amount (Net Total + Fine) .");

			$("#txtPaidAmount").focus( );

			return false;
		}
		

		if (!objFV.validate("txtFine", "N", "Please enter the valid Fine Amount."))
			return false;
		
		if (iFine < 0)
		{
			showMessage("#RecordMsg", "alert", "Please enter a valid Fine Amount.");
			
			$("#txtFine").focus( );
			
			return false;
		}

