					$(this).attr("id", ("InstallmentDetails" + iIndex + "_" + iSubIndex));

					$(this).find("input.installmentAmount").attr("name", ("txtInstallmentAmount" + iIndex + "_" + iSubIndex));
					$(this).find("input.installmentAmount").attr("id", ("txtInstallmentAmount" + iIndex + "_" + iSubIndex));
					$(this).find("input.installmentAmount").attr("rel", iIndex);
