	$(document).on("change", "#frmRecord select.feeCategory", function( )
	{
		var iIndex = $(this).attr("name").replace("ddFeeCategory", "");

		if ($(this).val( ) == "Other")
		{
			$(this).replaceWith($("<input/>", {"type":"text", "name":("txtFeeCategory" + iIndex), "id":("txtFeeCategory" + iIndex), "class":"textbox feeCategory", "maxlength":"100", "spellcheck":"true", "style":"width:98%" }));
			$("#txtFeeCategory" + iIndex).focus( );
		}


		resetFeeCategories( );
	});


	$(document).on("keyup", "#frmRecord input.feeCategory", function(e)
	{
		if ($(this).val( ) == "" && e.keyCode == 8)
		{
			var iIndex = $(this).attr("name").replace("txtFeeCategory", "");

			$(this).parent( ).html($("#FeeRecord select").parent( ).html( ).replaceAll("[Index]", iIndex));
			$("#ddFeeCategory" + iIndex).focus( );
		}


		resetFeeCategories( );
	});


	$(".feeInstallments").change(function( )
	{
		var iIndex      = $(this).attr("id").replace("ddInstallments", "");
		var iDueAmount  = parseInt($("#txtDueAmount" + iIndex).val( ));
		var iConcession = parseInt($("#txtConcession" + iIndex).val( ));

		iDueAmount      = ((isNaN(iDueAmount)) ? 0 : iDueAmount);
		iConcession     = ((isNaN(iConcession)) ? 0 : iConcession);


		if ($(this).val( ) == "1" || (iDueAmount - iConcession) == 0)
		{
			$(this).val("1");

			$("#Installments" + iIndex).hide("blind");
		}

		else
		{
			if ($("#Installments" + iIndex).css('display') == "none")
				$("#Installments" + iIndex).show("blind");
		}


		installmentDetails(iIndex);


		var bInstallments = false;

		$(".feeInstallments").each(function( )
		{
			if ($(this).val( ) != "1")
				bInstallments = true;
		});

		if (bInstallments == true)
		{
			if ($("#InstallmentsType").css("display") != "block")
				$("#InstallmentsType").show("blind");
		}

		else
		{
			if ($("#InstallmentsType").css("display") == "block")
				$("#InstallmentsType").hide("blind");
		}
	});


	$(".installmentAmount").blur(function( )
	{
		var iIndex = $(this).attr("rel");

		$("#txtPayableAmount" + iIndex).val($("#txtInstallmentAmount" + iIndex + "_1").val( ));

		updateTotalFee( );
	});


	$(document).on("blur", ".dueAmount, .concession", function( )
	{
		var iIndex = $(this).attr("id").replace("txtDueAmount", "").replace("txtConcession", "");

		installmentDetails(iIndex);
		updateTotalFee( );
	});


	$("#frmRecord").submit(function( )
	{
		var objFV  = new FormValidator("frmRecord", "RecordMsg");
		var iCount = parseInt($("#Count").val( ));


		if ($("#txtTaxRate").length == 1)
		{
			if (!objFV.validate("txtTaxRate", "B,F", "Please enter a valid Tax Rate (%)."))
				return false;
		}


		if (objFV.value("ddPaid") == "Y")
		{
			if (!objFV.validate("txtPaidDate", "B", "Please select the Paid Date."))
				return false;

			if (!objFV.validate("txtFine", "N", "Please enter the valid Fine Amount."))
				return false;

			if (!objFV.validate("ddPaymentMode", "B", "Please select the Payment Mode."))
				return false;

			if (objFV.value("ddPaymentMode") == "BC" || objFV.value("ddPaymentMode") == "BT" || objFV.value("ddPaymentMode") == "OL" || objFV.value("ddPaymentMode") == "CH")
			{
				if (!objFV.validate("ddBankAccount", "B", "Please select the Bank Account."))
					return false;
			}

			if (objFV.value("ddPaymentMode") == "CH")
			{
				if (!objFV.validate("txtChequeNo", "B", "Please enter the Cheque No."))
					return false;
			}
		}


		var bFlag = true;

		for (var i = 0; i < iCount; i ++)
		{
			var iDueAmount  = parseInt($("#txtDueAmount" + i).val( ));
			var iConcession = parseInt($("#txtConcession" + i).val( ));

			iDueAmount     = ((isNaN(iDueAmount)) ? 0 : iDueAmount);
			iConcession    = ((isNaN(iConcession)) ? 0 : iConcession);


			if ($("#ddFeeCategory" + i).length == 1)
			{
				if (!objFV.validate(("ddFeeCategory" + i), "B", "Please select the Fee Category."))
				{
					bFlag = false;

					return false;
				}

				if (!objFV.validate(("txtDueAmount" + i), "B,N", "Please enter a valid Due Amount."))
				{
					bFlag = false;

					return false;
				}

				if (iDueAmount <= 0)
				{
					showMessage("#RecordMsg", "alert", "Please enter a valid Due Amount.");

					$("#txtDueAmount" + i).focus( );

					bFlag = false;

					return false;
				}

				if (!objFV.validate(("txtConcession" + i), "B,N", "Please enter a valid Concession Amount."))
				{
					bFlag = false;

					return false;
				}

				if (iConcession < 0 || iConcession > iDueAmount)
				{
					showMessage("#RecordMsg", "alert", "Please enter a valid Concession Amount.");

					$("#txtConcession" + i).focus( );

					bFlag = false;

					return false;
				}
			}

			else if ($("#txtFeeCategory" + i).length == 1)
			{
				if (!objFV.validate(("txtFeeCategory" + i), "B", "Please enter the Fee Category Name."))
				{
					bFlag = false;

					return false;
				}

				if (!objFV.validate(("txtDueAmount" + i), "B,N", "Please enter a valid Due Amount."))
				{
					bFlag = false;

					return false;
				}

				if (iDueAmount <= 0)
				{
					showMessage("#RecordMsg", "alert", "Please enter a valid Due Amount.");

					$("#txtDueAmount" + i).focus( );

					bFlag = false;

					return false;
				}

				if (!objFV.validate(("txtConcession" + i), "B,N", "Please enter a valid Concession Amount."))
				{
					bFlag = false;

					return false;
				}

				if (iConcession < 0 || iConcession > iDueAmount)
				{
					showMessage("#RecordMsg", "alert", "Please enter a valid Concession Amount.");

					$("#txtConcession" + i).focus( );

					bFlag = false;

					return false;
				}


				var iPayableAmount      = (iDueAmount - iConcession);
				var iInstallments       = parseInt($("#ddInstallments" + i).val( ));
				var iInstallmentsAmount = 0;

				if (iInstallments > 1)
				{
					for (var j = 1; j <= iInstallments; j ++)
					{
						if (!objFV.validate(("txtInstallmentAmount" + i + "_" + j), "B,N", "Please enter the Installment # " + j + " Amount."))
						{
							bFlag = false;

							return false;
						}

						iInstallmentsAmount += parseInt($("#txtInstallmentAmount" + i + "_" + j).val( ));
					}


					if (iPayableAmount != iInstallmentsAmount)
					{
						showMessage("#RecordMsg", "alert", "The Due Amount and Installments Amount should be Equal.");

						bFlag = false;

						return false;
					}
				}


				if (bFlag == false)
					return false;
			}
		}


		if (bFlag == false)
			return false;


		$("#BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );

		return true;
	});
});


function updateTotalFee( )
{
	var iCount = parseInt($("#Count").val( ));
	var iTotal = 0;

	for (var i = 0; i < iCount; i ++)
	{
		if ($("#txtPayableAmount" + i).length == 1 && !isNaN($("#txtPayableAmount" + i).val( )))
			iTotal += parseInt($("#txtPayableAmount" + i).val( ));
	}



	if ($("#txtTaxRate").length == 1)
	{
		var fTaxRate       = parseFloat($("#txtTaxRate").val( ));
		var iTaxableAmount = 0;

		fTaxRate = ((isNaN(fTaxRate) || fTaxRate < 0 || fTaxRate > 100) ? 0 : fTaxRate);


		for (var i = 0; i < iCount; i ++)
		{
			if ($("#txtPayableAmount" + i).length == 1 && !isNaN($("#txtPayableAmount" + i).val( )) && $("#Taxable" + i).length == 1 && $("#Taxable" + i).val( ) == "Y")
				iTaxableAmount += parseInt($("#txtPayableAmount" + i).val( ));
		}


		var iTax = ((iTaxableAmount > 0) ? Math.round((iTaxableAmount / 100) * fTaxRate) : 0);

		iTax    = ((isNaN(iTax)) ? 0 : iTax);
		iTotal += iTax;

		$("#Tax").html(iTax);
	}


   	$("#Total").html(iTotal);
}


function installmentDetails(iIndex)
{
	var iDueAmount     = parseInt($("#txtDueAmount" + iIndex).val( ));
	var iConcession    = parseInt($("#txtConcession" + iIndex).val( ));
	var iPayableAmount = 0;


	iDueAmount     = ((isNaN(iDueAmount)) ? 0 : iDueAmount);
	iConcession    = ((isNaN(iConcession)) ? 0 : iConcession);
	iPayableAmount = (iDueAmount - iConcession);


	if ($("#Installments" + iIndex).length == 0)
	{
		$("#txtPayableAmount" + iIndex).val(iPayableAmount);

		updateTotalFee( );

		return false;
	}


	var iInstallments      = parseInt($("#ddInstallments" + iIndex).val( ));
	var iInstallmentAmount = Math.floor(iPayableAmount / iInstallments);

	if (iInstallments == 1)
	{
		$("#txtPayableAmount" + iIndex).val(iPayableAmount);

		updateTotalFee( );

		return false;
	}


	for (var i = 1; i <= 6; i ++)
	{
		if (i <= iInstallments)
		{
			if (i == iInstallments)
				$("#txtInstallmentAmount" + iIndex + "_" + i).val((iInstallmentAmount + (iPayableAmount - (iInstallmentAmount * iInstallments))));

			else
			{
				if (i == 1)
					$("#txtPayableAmount" + iIndex).val(iInstallmentAmount);

				$("#txtInstallmentAmount" + iIndex + "_" + i).val(iInstallmentAmount);
			}


			if ($("#InstallmentDetails" + iIndex + "_" + i).css('display') == "none")
				$("#InstallmentDetails" + iIndex + "_" + i).show("blind");
		}

		else
		{
			$("#InstallmentDetails" + iIndex + "_" + i).hide("blind");
			$("#txtInstallmentAmount" + iIndex + "_" + i).val("0");
		}
	}


	updateTotalFee( );
}


function resetFeeCategories( )
{
	$("#FeeDetails .feeRecord select.feeCategory").each(function( )
	{
		var objSelect = $(this);

		$("#" + objSelect.attr("id") + " option").attr("disabled", false);


		$("#FeeDetails .feeRecord .feeCategory").each(function( )
		{
			var objControl = $(this);

			if (objControl.val( ) == "")
				return false;

			console.log(objSelect.attr("id"), objControl.attr("id"), $("#" + objSelect.attr("id") + " option").length);

			$("#" + objSelect.attr("id") + " option").each(function( )
			{
				console.log(objSelect.attr("id"), objControl.attr("id"), objSelect.val( ), objControl.val( ), $(this).val( ));


				if (objControl != objSelect && objSelect.val( ) != $(this).val( ) && $(this).val( ) == objControl.val( ))
				{
					$(this).attr("disabled", true);

					return false;
				}
			});
		});
	});
}

