	{
		getClassSectionsList("#frmRecord #ddSchool", "#frmRecord #Classes", "", "M");
		getStudentsList("#frmRecord #ddSchool", "#frmRecord #ddSession", "#frmRecord .class", "#frmRecord #Students", "#frmRecord #ddStatus", "M");
	});


	$("#frmRecord #ddSession, #frmRecord #ddStatus").change(function( )
	{
		getStudentsList("#frmRecord #ddSchool", "#frmRecord #ddSession", "#frmRecord .class", "#frmRecord #Students", "#frmRecord #ddStatus", "M");
	});


	$(document).on("click", "#frmRecord .class", function( )
	{
		getStudentsList("#frmRecord #ddSchool", "#frmRecord #ddSession", "#frmRecord .class", "#frmRecord #Students", "#frmRecord #ddStatus", "M");
	});
	

	$("#frmRecord span a").click(function( )
	{
		var sData   = $(this).attr("rel");
		var sParams = sData.split("|");

		$("#frmRecord ." + sParams[1]).each(function( )
		{
			if (sParams[0] == "Check")
				$(this).prop("checked", true);

			else
				$(this).prop("checked", false);
		});


		if (sParams[1] == "class")
			getStudentsList("#frmRecord #ddSchool", "#frmRecord #ddSession", "#frmRecord .class", "#frmRecord #Students", "#frmRecord #ddStatus", "M");


		return false;
	});
	
	
	$("#frmRecord #BtnReset").click(function( )
	{
		$("#frmRecord")[0].reset( );
		$("#RecordMsg").hide( );


		$("#frmRecord #Students").html("");

		if ($("#frmRecord select#ddSchool").length > 0)
		{
			$("#frmRecord #Classes").html("");

			$("#frmRecord #ddSchool").focus( );
		}

		return false;
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");
		var bFlag = false;

		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;

		if (!objFV.validate("ddSession", "B", "Please select the Session."))
			return false;

		$("#frmRecord .class").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false)
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one Class.");

			return false;
		}


		bFlag = false;
		
		$("#frmRecord .feeType").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false)
		{
			showMessage("#RecordMsg", "alert", "Please select at-least one Fee Type.");

			return false;
		}

		if (!objFV.validate("ddBillingMonth", "B", "Please select the Billing Month."))
			return false;

		if (!objFV.validate("ddBillingYear", "B", "Please select the Billing Year."))
			return false;
		
		
		var objMinIssueDate = parseDate($("#frmRecord #txtIssueDate").attr("date"));
		var objIssueDate    = parseDate($("#frmRecord #txtIssueDate").val( ));
		
		if (objIssueDate.getTime( ) <= objMinIssueDate.getTime( ))
		{
			showMessage("#RecordMsg", "alert", "You cannot select this Issue Date (Old Dated entries are Restricted).");

			return false;
		}
		
		
		var objMinDueDate = parseDate($("#frmRecord #txtDueDate").attr("date"));
		var objDueDate    = parseDate($("#frmRecord #txtDueDate").val( ));
		
		if (objDueDate.getTime( ) <= objMinDueDate.getTime( ))
		{
			showMessage("#RecordMsg", "alert", "You cannot select this Due Date (Old Dated entries are Restricted).");

			return false;
		}
		
		if (objDueDate.getTime( ) < objIssueDate.getTime( ))
		{
			showMessage("#RecordMsg", "alert", "Invalid Due Date, cannot be less than the Issue Date.");

			return false;
		}
		
		
		if ($("#txtTaxRate").length == 1)
		{
			if (!objFV.validate("txtTaxRate", "B,F", "Please enter a valid Tax Rate (%)."))
				return false;			
		}


		$("#frmRecord #BtnGenerate").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});

