$(document).ready(function( )
{
	$("#frmCollect #BillNo").focus( );


	$("#frmCollect").submit(function( )
	{
		var sBillNo = $("#frmCollect #BillNo").val( );

		if (sBillNo == "")
			return false;

		$.colorbox({ href:("billing/collect-fee.php?BillNo=" + sBillNo), width:"900px", height:"640px", iframe:true, opacity:"0.50", overlayClose:false });
	});


	$("#BtnImport").button({ icons:{ primary:'ui-icon-transferthick-e-w' } });

	$("#BtnImport").click(function( )
	{
		$.colorbox({ href:"billing/import-fee-collection.php", width:"500px", height:"500", iframe:true, opacity:"0.50", overlayClose:false });
	});
});


function clearField( )
{
	$("#frmCollect #BillNo").val("");
	$("#frmCollect #BillNo").select( ).focus( );
}


function printFee(iFeeId)
{
	$.post("ajax/billing/print-fee-receipt.php",
		{ FeeId:iFeeId },

		function (sResponse)
		{
			var sParams = sResponse.split("|-|");

			showMessage("#PageMsg", sParams[0], sParams[1]);
		},

		"text");
}

