var objTable;

$(document).ready(function( )
{
	if (parseInt($("#TotalRecords").val( )) > 100)
	{
		objTable = $("#DataGrid").dataTable(   { sDom            : '<"H"f<"toolbar"><"TableTools">>t<"F"ip>',
												 aoColumnDefs    : [ { bSortable:false, aTargets:[7] } ],
												 oLanguage       : { sEmptyTable:"No record found", sInfoEmpty:"0 records", sZeroRecords:"No matching record found" },
												 aaSorting       : [ [ 0, "desc" ] ],
												 bJQueryUI       : true,
												 sPaginationType : "full_numbers",
												 bPaginate       : true,
												 bLengthChange   : false,
												 iDisplayLength  : parseInt($("#RecordsPerPage").val( )),
												 bFilter         : true,
												 bSort           : true,
												 bInfo           : true,
												 bStateSave      : false,
												 bProcessing     : false,
												 bAutoWidth      : false,
												 bServerSide     : true,
												 sAjaxSource     : "ajax/payroll/get-payroll.php",

												 fnServerData    : function (sSource, aoData, fnCallback)
																   {
																		if ($("div.toolbar #School").length > 0)
																			aoData.push({ name:"School", value:$("div.toolbar #School").val( ) });

																		if ($("div.toolbar #Department").length > 0)
																			aoData.push({ name:"Department", value:$("div.toolbar #Department").val( ) });

																		if ($("#tabs-1 div.toolbar #Month").length > 0)
																			aoData.push({ name:"Month", value:$("div.toolbar #Month").val( ) });

																		if ($("#tabs-1 div.toolbar #Year").length > 0)
																			aoData.push({ name:"Year", value:$("div.toolbar #Year").val( ) });

																		if ($("#tabs-1 div.toolbar #PaymentMode").length > 0)
																			aoData.push({ name:"PaymentMode", value:$("div.toolbar #PaymentMode").val( ) });

																		if ($("#tabs-1 div.toolbar #Posted").length > 0)
																			aoData.push({ name:"Posted", value:$("div.toolbar #Posted").val( ) });


																		$.getJSON(sSource, aoData, function(jsonData)
																		{
																			fnCallback(jsonData);


																			$("#DataGrid tbody tr").each(function(iIndex)
																			{
																				$(this).attr("id", $(this).find("img:first-child").attr("id"));
																				$(this).find("td:first-child").addClass("position");

																				if (!$(this).find("img.icnDelete"))
																					$(this).addClass("noDelete");
																			});


																			if ($("#SelectButtons").length == 1)
																			{
																				if (objTable && objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																					$("#SelectButtons").show( );

																				else
																					$("#SelectButtons").hide( );
																			}
																		});
																   },

												 fnDrawCallback  : function( )
																   {
																	   $(".details").tipTip( );
																   },

												 fnInitComplete  : function( )
																   {
																		$.post("ajax/payroll/get-payroll-filters.php",
																			   {},

																			   function (sResponse)
																			   {
																				$("div.toolbar").html(sResponse);
																			   },

																			   "text");


																		var iSchool     = 0;
																		var iDepartment = 0;
																		var iMonthYear  = 0;

																		$("#DataGrid thead tr th").each(function(iIndex)
																		{
																			if ($(this).text( ) == "School")
																				iSchool = iIndex;

																			if ($(this).text( ) == "Department")
																				iDepartment = iIndex;

																			if ($(this).text( ) == "Month/Year")
																				iMonthYear = iIndex;
																		});

																		this.fnFilter("", iSchool);
																		this.fnFilter("", iDepartment);
																		this.fnFilter("", iMonthYear);
																   }
												 } );
	}

	else
	{
		objTable = $("#DataGrid").dataTable(   { sDom            : '<"H"f<"toolbar"><"TableTools">>t<"F"ip>',
												 aoColumnDefs    : [ { bSortable:false, aTargets:[7] } ],
												 oLanguage       : { sEmptyTable:"No record found", sInfoEmpty:"0 records", sZeroRecords:"No matching record found" },
												 aaSorting       : [ [ 0, "desc" ] ],
												 bJQueryUI       : true,
												 sPaginationType : "full_numbers",
												 bPaginate       : true,
												 bLengthChange   : false,
												 iDisplayLength  : parseInt($("#RecordsPerPage").val( )),
												 bFilter         : true,
												 bSort           : true,
												 bInfo           : true,
												 bStateSave      : false,
												 bProcessing     : false,
												 bAutoWidth      : false,

												 fnDrawCallback  : function( )
																   {
																	   $(".details").tipTip( );
																   },

												 fnInitComplete  : function( )
																   {
																		$.post("ajax/payroll/get-payroll-filters.php",
																			   {},

																			   function (sResponse)
																			   {
																				$("div.toolbar").html(sResponse);
																			   },

																			   "text");


																		var iSchool     = 0;
																		var iDepartment = 0;
																		var iMonthYear  = 0;

																		$("#DataGrid thead tr th").each(function(iIndex)
																		{
																			if ($(this).text( ) == "School")
																				iSchool = iIndex;

																			if ($(this).text( ) == "Department")
																				iDepartment = iIndex;

																			if ($(this).text( ) == "Month/Year")
																				iMonthYear = iIndex;
																		});

																		this.fnFilter("", iSchool);
																		this.fnFilter("", iDepartment);
																		this.fnFilter("", iMonthYear);
																   }
												} );
	}


	$(document).on("change", "div.toolbar #School", function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );


		var iColumn = 0;

		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "School")
				iColumn = iIndex;
		});


		objTable.fnFilter($(this).val( ), iColumn);


		if (parseInt($("#TotalRecords").val( )) <= 100)
		{
			$("#DataGrid td.position").each(function(iIndex)
			{
				var objRow = objTable.fnGetPosition($(this).closest('tr')[0]);

				objTable.fnUpdate((iIndex + 1), objRow, 0);
			});

			objTable.fnDraw( );
		}
	});


	$(document).on("change", "div.toolbar #Department", function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );


		var iColumn = 0;

		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Department")
				iColumn = iIndex;
		});


		objTable.fnFilter($(this).val( ), iColumn);


		if (parseInt($("#TotalRecords").val( )) <= 100)
		{
			$("#DataGrid td.position").each(function(iIndex)
			{
				var objRow = objTable.fnGetPosition($(this).closest('tr')[0]);

				objTable.fnUpdate((iIndex + 1), objRow, 0);
			});

			objTable.fnDraw( );
		}
	});


	$(document).on("change", "div.toolbar #Month, div.toolbar #Year", function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );


		var iColumn = 0;

		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Month/Year")
				iColumn = iIndex;
		});


		if (parseInt($("#TotalRecords").val( )) <= 100)
			objTable.fnFilter(($("div.toolbar #Month").val( ) + " " + $("div.toolbar #Year").val( )), iColumn);

		else
			objTable.fnFilter($(this).val( ), iColumn);


		if (parseInt($("#TotalRecords").val( )) <= 100)
		{
			$("#DataGrid td.position").each(function(iIndex)
			{
				var objRow = objTable.fnGetPosition($(this).closest('tr')[0]);

				objTable.fnUpdate((iIndex + 1), objRow, 0);
			});

			objTable.fnDraw( );
		}
	});


	$(document).on("change", "div.toolbar #PaymentMode, div.toolbar #Posted", function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );


		objTable.fnFilter($(this).val( ), 0);
	});	


	$("#BtnSelectAll").click(function( )
	{
		var iSchool     = 0;
		var iDepartment = 0;
		var iMonthYear  = 0;

		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "School")
				iSchool = iIndex;

			if ($(this).text( ) == "Department")
				iDepartment = iIndex;

			if ($(this).text( ) == "Month/Year")
				iMonthYear = iIndex;
		});


		var objRows   = objTable.fnGetNodes( );
		var bSelected = false;


		if (parseInt($("#TotalRecords").val( )) <= 100)
		{
			var sSchool     = "";
			var sDepartment = "";
			var sMonth      = "";
			var sYear       = "";

			if ($("div.toolbar #School").length > 0)
				sSchool = $("div.toolbar #School").val( );

			if ($("div.toolbar #Department").length > 0)
				sDepartment = $("div.toolbar #Department").val( );

			if ($("div.toolbar #Month").length > 0)
				sMonth = $("div.toolbar #Month").val( );

			if ($("div.toolbar #Year").length > 0)
				sYear = $("div.toolbar #Year").val( );


			for (var i = 0; i < objRows.length; i ++)
			{
				if ($(objRows[i]).find("img.icnDelete").length == 0)
				{
					$(objRows[i]).removeClass("selected");

					continue;
				}


				if ( (sSchool == "" || sSchool == objTable.fnGetData(objRows[i])[iSchool]) &&
				     (sDepartment == "" || sDepartment == objTable.fnGetData(objRows[i])[iDepartment]) &&
				     ((sMonth == "" && sYear == "") || (objTable.fnGetData(objRows[i])[iMonthYear].indexOf(sMonth) >= 0 && objTable.fnGetData(objRows[i])[iMonthYear].indexOf(sYear) >= 0)) )
				{
					if (!$(objRows[i]).hasClass("selected"))
					{
						$(objRows[i]).addClass("selected");

						bSelected = true;
					}
				}

				else
					$(objRows[i]).removeClass("selected");
			}
		}

		else
		{
			for (var i = 0; i < objRows.length; i ++)
			{
				if (!$(objRows[i]).hasClass("selected"))
				{
					$(objRows[i]).addClass("selected");

					bSelected = true;
				}
			}
		}

		if (bSelected == true)
			$("#BtnMultiDelete").show( );
	});


	$("#BtnSelectNone").click(function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );
	});


	$(document).on("click", "#DataGrid tr", function( )
	{
		if ($(this).find("img.icnDelete").length == 0)
			return;


		if ($(this).hasClass("selected"))
			$(this).removeClass("selected");

		else
			$(this).addClass("selected");


		var bSelected = false;
		var objRows   = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if ($(objRows[i]).hasClass("selected"))
			{
				bSelected = true;

				break;
			}
		}

		if (bSelected == true)
			$("#BtnMultiDelete").show( );

		else
			$("#BtnMultiDelete").hide( );
	});


	$("#tabs-1 .TableTools").prepend('<button id="BtnMultiDelete">Delete Selected Rows</button>');
	$("#BtnMultiDelete").button({ icons:{ primary:'ui-icon-trash' } });
	$("#BtnMultiDelete").hide( );


	$(document).on("click", "#BtnMultiDelete", function( )
	{
		var sPayroll        = "";
		var objSelectedRows = new Array( );

		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if ($(objRows[i]).hasClass("selected"))
			{
				if (sPayroll != "")
					sPayroll += ",";

				sPayroll += objRows[i].id;

				objSelectedRows.push(objRows[i]);
			}
		}

		if (sPayroll != "")
		{
			$("#ConfirmMultiDelete").dialog(   { resizable : false,
												 width     : 420,
												 height    : 110,
												 modal     : true,
												 buttons   : { "Delete" : function( )
																		   {
																				 $.post("ajax/payroll/delete-payroll.php",
																					{ Payroll:sPayroll },

																					function (sResponse)
																					{
																						var sParams = sResponse.split("|-|");

																						showMessage("#GridMsg", sParams[0], sParams[1]);

																						if (sParams[0] == "success")
																						{
																							 for (var i = 0; i < objSelectedRows.length; i ++)
																								  objTable.fnDeleteRow(objSelectedRows[i]);

																							  $("#BtnMultiDelete").hide( );


																							  if ($("#SelectButtons").length == 1)
																							  {
																								if (objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																									$("#SelectButtons").show( );

																								else
																									$("#SelectButtons").hide( );
																							  }
																						}
																					},

																					"text");

																				$(this).dialog("close");
																		   },

																	 Cancel  : function( )
																			   {
																					$(this).dialog("close");
																			   }
													  }
											});
		}
	});


	$(document).on("click", "#DataGrid .icnEdit", function(event)
	{
		var iPayrollId = this.id;
		var iIndex     = objTable.fnGetPosition($(this).closest('tr')[0]);

		$.colorbox({ href:("payroll/edit-payroll.php?PayrollId=" + iPayrollId + "&Index=" + iIndex), width:"900px", height:"500px", iframe:true, opacity:"0.50", overlayClose:false });

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnView", function(event)
	{
		var iPayrollId = this.id;

		$.colorbox({ href:("payroll/view-payroll.php?PayrollId=" + iPayrollId), width:"900", height:"500px", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnDelete", function(event)
	{
		var iPayrollId = this.id;
		var objRow     = objTable.fnGetPosition($(this).closest('tr')[0]);

		$("#ConfirmDelete").dialog(   { resizable : false,
										width     : 420,
										height    : 110,
										modal     : true,
										buttons   : { "Delete" : function( )
																  {
																		$.post("ajax/payroll/delete-payroll.php",
																			{ Payroll:iPayrollId },

																			function (sResponse)
																			{
																				var sParams = sResponse.split("|-|");

																				showMessage("#GridMsg", sParams[0], sParams[1]);

																				if (sParams[0] == "success")
																					objTable.fnDeleteRow(objRow);


																				if ($("#SelectButtons").length == 1)
																				{
																					if (objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																						$("#SelectButtons").show( );

																					else
																						$("#SelectButtons").hide( );
																				}
																			},

																			"text");

																		$(this).dialog("close");
																  },

															Cancel  : function( )
																	  {
																			$(this).dialog("close");
																	  }
											 }
									  });

		event.stopPropagation( );
	});



	$("#frmRecord #ddSchool, #frmRecord #ddDepartment, #frmRecord #ddStatus").change(function( )
	{
		getEmployeesList("#frmRecord #ddSchool", "", "#frmRecord #ddDepartment", "", "#frmRecord #ddEmployee", "#frmRecord #ddStatus");
	});


	$("#frmRecord #BtnReset").click(function( )
	{
		$('#frmRecord')[0].reset( );
		$("#RecordMsg").hide( );

		clearList("#frmRecord #ddEmployee");

		if ($("#frmRecord select#ddSchool").length > 0)
			$("#frmRecord #ddSchool").focus( );

		else
			$("#frmRecord #ddDepartment").focus( );

		return false;
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");


		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;

		if (!objFV.validate("ddMonth", "B", "Please select the Salary Month."))
			return false;

		if (!objFV.validate("ddYear", "B", "Please select the Salary Year."))
			return false;


		if ($("#ddBankAccount").length == 1)
		{
			if (!objFV.validate("ddBankAccount", "B", "Please select the Salary Bank Account."))
				return false;
		}		


		$("#frmRecord #BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});



	if ($("#frmPayroll #BtnSave").length == 1)
	{
		$("#frmPayroll #txtSalaryDate").datepicker(
		{
			showOn          : "both",
			buttonImage     : "images/icons/calendar.gif",
			buttonImageOnly : true,
			dateFormat      : "yy-mm-dd",
			minDate         :  parseDate($("#txtSalaryDate").attr("date"), true)
		});


		$("#frmPayroll #BtnSave").button({ icons:{ primary:'ui-icon-disk' } });	
		$("#frmPayroll #BtnClear").button({ icons:{ primary:'ui-icon-refresh' } });	
	}


	$("#frmPayroll #ddMonth, #frmPayroll #ddYear").change(function( )
	{
		var objDate = new Date($("#frmPayroll #ddYear").val( ), parseInt($("#frmPayroll #ddMonth").val( )), 0, 12, 12, 12, 0);

		$("#frmPayroll #txtSalaryDate").val(objDate.getFullYear() + "-" + new String((objDate.getMonth( ) + 1)).leftPadding(2, '0') + "-" + new String(objDate.getDate()).leftPadding(2, '0'));
	});


	$(document).on("click", "#frmPayroll #BtnSave", function( )
	{
		$("#frmPayroll #Action").val("SET");

		return true;
	});


	$(document).on("click", "#frmPayroll #BtnClear", function( )
	{
		$("#frmPayroll #Action").val("CLEAR");

		return true;
	});


	$("#frmPayroll").submit(function( )
	{
		var objFV = new FormValidator("frmPayroll", "PayrollMsg");


		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;

		if (!objFV.validate("ddMonth", "B", "Please select the Salary Month."))
			return false;

		if (!objFV.validate("ddYear", "B", "Please select the Salary Year."))
			return false;


		var objMinDate    = parseDate($("#txtSalaryDate").attr("date"));
		var objSalaryDate = parseDate($("#txtSalaryDate").val( ));

		if (objSalaryDate.getTime( ) <= objMinDate.getTime( ))
		{
			showMessage("#PayrollMsg", "alert", "You cannot select this Salary Date (Old Dated entries are Restricted).");

			return false;
		}


		$("#frmPayroll #BtnSave").attr('disabled', true);
		$("#PayrollMsg").hide( );


		$.post("ajax/payroll/save-payroll-date.php",
			$("#frmPayroll").serialize( ),

			function (sResponse)
			{
				var sParams = sResponse.split("|-|");

				showMessage("#PayrollMsg", sParams[0], sParams[1]);


				$("#frmPayroll #BtnSave").attr('disabled', false);
			},

			"text");


		return false;
	});
});


function updateRecord(iPayrollId, iRow, sFields)
{
	if (parseInt($("#TotalRecords").val( )) <= 100)
	{
		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Payable Salary")
				objTable.fnUpdate(sFields[0], iRow, iIndex, false);

			else if ($(this).text( ) == "Options")
				objTable.fnUpdate(sFields[1], iRow, iIndex, false);
		});


		$(".details").tipTip( );
	}

	else
		objTable.fnStandingRedraw( );
}

