$(document).ready(function( )
{
	$("#txtSalaryDate").datepicker(
	{
		showOn          : "both",
		buttonImage     : "images/icons/calendar.gif",
		buttonImageOnly : true,
		dateFormat      : "yy-mm-dd"
	});


	$("#txtIncomeTax, #txtAdditionalTax").blur(function( )
	{
		var iPayableSalary = parseInt($("#Payable").val( ));
		var iIncomeTax     = parseInt($("#txtIncomeTax").attr("rel"));
		var iAdditionalTax = parseInt($("#txtAdditionalTax").attr("rel"));


		var iPayable = (iPayableSalary + iIncomeTax + iAdditionalTax);

		if (!isNaN($("#txtIncomeTax").val( )))
			iPayable -= parseInt($("#txtIncomeTax").val( ));

		else
			$("#txtIncomeTax").val("0");

		if (!isNaN($("#txtAdditionalTax").val( )))
			iPayable -= parseInt($("#txtAdditionalTax").val( ));

		else
			$("#txtAdditionalTax").val("0");

		$("#PayableSalary").html(iPayable);
	});


	$("#frmRecord #ddPaymentMode").change(function( )
	{
		if ($(this).val( ) == "BT")
		{
			if ($("#AccountDetails").css("display") != "block")
				$("#AccountDetails").show("blind");

			if ($("#ChequeDetails").css("display") == "block")
				$("#ChequeDetails").hide("blind");

			if ($("#BankAccount").css("display") != "block")
				$("#BankAccount").show("blind");
		}

		else if ($(this).val( ) == "CH")
		{
			if ($("#ChequeDetails").css("display") != "block")
				$("#ChequeDetails").show("blind");

			if ($("#AccountDetails").css("display") == "block")
				$("#AccountDetails").hide("blind");

			if ($("#BankAccount").css("display") != "block")
				$("#BankAccount").show("blind");
		}

		else
		{
			if ($("#AccountDetails").css("display") == "block")
				$("#AccountDetails").hide("blind");

			if ($("#ChequeDetails").css("display") == "block")
				$("#ChequeDetails").hide("blind");

			if ($("#BankAccount").css("display") == "block")
				$("#BankAccount").hide("blind");
		}
	});


	$("#frmRecord #ddBankAccount").change(function( )
	{
		clearList("#ddChequeBook");
		clearList("#ddChequeNo");

		if ($("#frmRecord #ddBankAccount").val( ) == "")
			return;


		$.post("ajax/get-cheque-books.php",
			{ BankAccount:$("#frmRecord #ddBankAccount").val( ), ChequeBook:$("#ddChequeBook").attr("original") },

			function (sResponse)
			{
				$("#frmRecord #ddChequeBook").html(sResponse);
				$("#frmRecord #ddChequeBook").trigger("change");
			},

			"text");
	});


	$("#frmRecord #ddChequeBook").change(function( )
	{
		clearList("#ddChequeNo");

		if ($("#frmRecord #ddChequeBook").val( ) == "")
			return;


		$.post("ajax/get-cheque-nos.php",
			{ ChequeBook:$("#frmRecord #ddChequeBook").val( ), ChequeNo:$("#ddChequeNo").attr("original") },

			function (sResponse)
			{
				$("#frmRecord #ddChequeNo").html(sResponse);
			},

			"text");
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");


		if (!objFV.validate("txtIncomeTax", "B,N,S", "Please enter the valid Income Tax Amount."))
			return false;

		if (!objFV.validate("txtAdditionalTax", "B,N,S", "Please enter the valid Additional Tax Amount."))
			return false;

		if (!objFV.validate("ddPaymentMode", "B", "Please select the Payment Mode."))
			return false;

		if (objFV.value("ddPaymentMode") == "BT")
		{
			if (!objFV.validate("ddBank", "B", "Please select the Bank."))
				return false;

			if (!objFV.validate("txtBranchCode", "B", "Please enter the Branch Code."))
				return false;

			if (!objFV.validate("txtAccountNo", "B", "Please enter the Account No."))
				return false;
		}	

		if (objFV.value("ddPaymentMode") == "BT" || objFV.value("ddPaymentMode") == "CH")
		{
			if (!objFV.validate("ddBankAccount", "B", "Please select the Salary Bank Account."))
				return false;
		}

		if (objFV.value("ddPaymentMode") == "CH")
		{
			if (!objFV.validate("ddChequeBook", "B", "Please select the Cheque Book."))
				return false;

			if (!objFV.validate("ddChequeNo", "B", "Please select the Cheque No."))
				return false;
		}


		$("#BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );

		return true;
	});
});

