		getEmployeesList("#frmRecord #ddSchool", "", "#frmRecord #ddDepartment", "", "#frmRecord #ddEmployee", "R");
	});


	$("#frmRecord #ddSchool, #frmRecord #ddEmployee, #frmRecord #txtFromDate, #frmRecord #txtToDate").change(function( )
	{
		if ($("#frmRecord #ddEmployee").val( ) == "")
		{
			$("#LoanDetails").html("");

			return;
		}


		$.post("ajax/payroll/get-final-settlement-details.php",
			{ School:$("#frmRecord #ddSchool").val( ), Employee:$("#frmRecord #ddEmployee").val( ), FromDate:$("#frmRecord #txtFromDate").val( ), ToDate:$("#frmRecord #txtToDate").val( ) },

			function (sResponse)
