		if (!objFV.validate("ddEmployee", "B", "Please select the Employee."))
			return false;

		if (!objFV.validate("ddMonth", "B", "Please select the Salary Month."))
			return false;

		if (!objFV.validate("ddYear", "B", "Please select the Salary Year."))
			return false;

		if (!objFV.validate("txtFromDate", "B", "Please select the From Date."))
			return false;

		if (!objFV.validate("txtToDate", "B", "Please select the To Date."))
			return false;

		if ($("#ddBankAccount").length == 1)
		{
			if (!objFV.validate("ddBankAccount", "B", "Please select the Salary Bank Account."))
				return false;
		}		



		if (!objFV.validate("txtLeavesDeductions", "N", "Please enter the valid Leaves Deductions Amount."))
			return false;

		if (!objFV.validate("txtOthers", "N", "Please enter the valid Other Deductions Amount."))
			return false;

		if (!objFV.validate("txtMobileAllowance", "N", "Please enter the valid Mobile Allowance Amount."))
			return false;

		if (!objFV.validate("txtFuelAllowance", "N", "Please enter the valid Fuel Allowance Amount."))
			return false;

		if (!objFV.validate("txtReimbursement", "N", "Please enter the valid Reimbursement Amount."))
			return false;



		if (objFV.value("txtBonus") != "")
		{
			if (!objFV.validate("ddType", "B", "Please select the Bonus Type."))
				return false;

			if (!objFV.validate("txtBonus", "F", "Please enter a valid Amount/Percentage."))
				return false;			
		}


		$("#BtnGenerate").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});

