	$("#frmRecord #ddLoanType").change(function( )
	{
		if ($(this).val( ) == "PF")
			$("#frmRecord #Refundable").show("blind");

		else
		{
			if ($("#frmRecord #Refundable").css("display") == "block")
				$("#frmRecord #Refundable").hide("blind");

			$("#frmRecord #ddRefundable").val("Y");
		}
	});


	$("#frmRecord #ddLoanType, #frmRecord #ddRefundable").change(function( )
	{
		if ($("#frmRecord #ddLoanType").val( ) == "PF" && $("#frmRecord #ddRefundable").val( ) == "N")
		{
			$("#frmRecord #Adjustment").hide("blind");
			$("#frmRecord #ddInstallments").val("");
		}

		else
		{
			if ($("#frmRecord #Adjustment").css("display") != "block")
				$("#frmRecord #Adjustment").show("blind");
		}
	});


	$("#frmRecord #ddPaymentMode").change(function( )
	{
		if ($(this).val( ) == "BT" || $(this).val( ) == "CH")
		{
			if ($("#frmRecord #BankAccount").css('display') == "none")
				$("#frmRecord #BankAccount").show('blind');

			if ($(this).val( ) == "CH")
			{
				if ($("#frmRecord #ChequeDetails").css('display') == "none")
					$("#frmRecord #ChequeDetails").show('blind');
			}
		}

		else
		{
			if ($("#frmRecord #BankAccount").css('display') == "block")
				$("#frmRecord #BankAccount").hide( );
		}


		if ($(this).val( ) != "CH")
		{
			if ($("#frmRecord #ChequeDetails").css('display') == "block")
				$("#frmRecord #ChequeDetails").hide("blind");
		}
	});	


