			$("#frmRecord #ddSchool").focus( );

		else
			$("#frmRecord #ddDepartment").focus( );

		return false;
	});


	$("#ddInstallments, #txtAmount").change(function( )
	{
		var iInstallments      = parseInt($("#ddInstallments").val( ));
		var iLoanAmount        = parseInt($("#txtAmount").val( ));
		var iInstallmentAmount = Math.floor(iLoanAmount / iInstallments);

		if (iLoanAmount == 0 || isNaN(iLoanAmount))
		{
			iLoanAmount        = 0;
			iInstallmentAmount = 0;
		}


		if (iInstallments >= 1)
		{
			for (var i = 1; i <= 12; i ++)
			{
				if (i <= iInstallments)
				{
					$("#Installment" + i).show( );
					$("#txtAmount" + i).val(((i == 1) ? (iInstallmentAmount + (iLoanAmount - (iInstallmentAmount * iInstallments))) : iInstallmentAmount));
				}

				else
				{
					$("#Installment" + i).hide( );
					$("#txtAmount" + i).val("0");
				}
			}


			if ($("#Installments").css('display') == "none")
				$("#Installments").show('blind');
		}

		else if (iInstallments == 1 && $("#Installments").css('display') == "block")
			$("#Installments").hide('blind');
	});


	$("#ddMonth, #ddYear").change(function( )
	{
		for (var i = 1; i <= 12; i ++)
		{
			var objDate = new Date($("#ddYear").val( ), (parseInt($("#ddMonth").val( )) + i - 2), 1, 12, 12, 12, 0);
			var sDate   = objDate.toUTCString( ).split(" ");

			$("#Installment" + i + " span").html(sDate[2] + " " + sDate[3]);
		}
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");


		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;

		if (!objFV.validate("ddEmployee", "B", "Please select the Employee."))
			return false;

		if (!objFV.validate("txtAmount", "B,N", "Please enter the Loan Amount."))
			return false;

		if (!objFV.validate("txtDate", "B", "Please select the Loan Date."))
			return false;

		var objMinDate = parseDate($("#txtDate").attr("date"));
		var objDate    = parseDate($("#txtDate").val( ));

		if (objDate.getTime( ) <= objMinDate.getTime( ))
		{
			showMessage("#RecordMsg", "alert", "You cannot select this Loan Date (Old Dated entries are Restricted).");

			return false;
		}


		if (!objFV.validate("ddPaymentMode", "B", "Please select the Payment Mode."))
			return false;

		if (objFV.value("ddPaymentMode") == "BT" || objFV.value("ddPaymentMode") == "CH")
		{
			if (!objFV.validate("ddBankAccount", "B", "Please select the Bank Account."))
				return false;
		}

		if (objFV.value("ddPaymentMode") == "CH")
		{
			if (!objFV.validate("ddChequeBook", "B", "Please select the Cheque Book."))
				return false;

			if (!objFV.validate("ddChequeNo", "B", "Please select the Cheque No."))
				return false;
		}


		if (objFV.value("ddRefundable") == "Y")
		{
			var iInstallments       = parseInt($("#ddInstallments").val( ));
			var iLoanAmount         = parseInt($("#txtAmount").val( ));
			var iInstallmentsAmount = 0;

			for (var i = 1; i <= iInstallments; i ++)
			{
				if (!objFV.validate(("txtAmount" + i), "B,N", ("Please enter the valid Installment # " + i + " Amount.")))
					return false;

				iInstallmentsAmount += parseInt($("#txtAmount" + i).val( ));
			}


			if (iLoanAmount != iInstallmentsAmount)
			{
				showMessage("#RecordMsg", "alert", "The Loan Amount and Installments Amount should be Equal.");

				return false;
			}


			var iLoanYear   = parseInt($("#txtDate").val( ).substr(0, 4));
			var iLoanMonth  = parseInt($("#txtDate").val( ).substr(5, 2));
			var iStartYear  = parseInt($("#ddYear").val( ));
			var iStartMonth = parseInt($("#ddMonth").val( ));

			if (iStartYear < iLoanYear || (iStartYear == iLoanYear && iStartMonth < iLoanMonth))
			{
				showMessage("#RecordMsg", "alert", "The Loan Adjustment Starting Month/Year should be Equal or greater than Loan Month/Year.");

				return false;
			}
		}


		$("#frmRecord #BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});


function updateRecord(iLoanId, iRow, sFields)
{
	if (parseInt($("#TotalRecords").val( )) <= 100)
	{
		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Date")
				objTable.fnUpdate(sFields[0], iRow, iIndex, false);

			else if ($(this).text( ) == "Amount")
				objTable.fnUpdate(sFields[1], iRow, iIndex, false);

			else if ($(this).text( ) == "Remaining")
				objTable.fnUpdate(sFields[2], iRow, iIndex, false);

			else if ($(this).text( ) == "Options")
				objTable.fnUpdate(sFields[3], iRow, iIndex, false);
		});


		$(".details").tipTip( );
	}

	else
		objTable.fnStandingRedraw( );
}


function updateOptions(iRow, sOptions)
{
	$("#DataGrid thead tr th").each(function(iIndex)
	{
		if ($(this).text( ) == "Options")
			objTable.fnUpdate(sOptions, iRow, iIndex);
	});

	$(".details").tipTip( );
}

