		if (parseInt($("#TotalRecords").val( )) <= 100)
		{
			var sSchool     = "";
			var sDepartment = "";
			var sMonthYear  = "";

			if ($("div.toolbar #School").length > 0)
				sSchool = $("div.toolbar #School").val( );

			if ($("div.toolbar #Department").length > 0)
				sDepartment = $("div.toolbar #Department").val( );

			if ($("div.toolbar #MonthYear").length > 0)
				sMonthYear = $("div.toolbar #MonthYear").val( );


			for (var i = 0; i < objRows.length; i ++)
			{
				if ($(objRows[i]).find("img.icnDelete").length == 0)
				{
					$(objRows[i]).removeClass("selected");

					continue;
				}


				if ( (sSchool == "" || sSchool == objTable.fnGetData(objRows[i])[iSchool]) &&
				     (sDepartment == "" || sDepartment == objTable.fnGetData(objRows[i])[iDepartment]) &&
				     (sMonthYear == "" || sMonthYear == objTable.fnGetData(objRows[i])[iMonthYear]) )
				{
					if (!$(objRows[i]).hasClass("selected"))
					{
						$(objRows[i]).addClass("selected");

						bSelected = true;
					}
				}

				else
					$(objRows[i]).removeClass("selected");
			}
		}

		else
		{
			for (var i = 0; i < objRows.length; i ++)
			{
				if (!$(objRows[i]).hasClass("selected"))
				{
					$(objRows[i]).addClass("selected");

					bSelected = true;
				}
			}
		}

		if (bSelected == true)
			$("#BtnMultiDelete").show( );
	});


