function updateRecord(iAdjustmentId, iRow, sFields)
{
	if (parseInt($("#TotalRecords").val( )) <= 100)
	{
		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Month/Year")
				objTable.fnUpdate(sFields[0], iRow, iIndex, false);

			else if ($(this).text( ) == "Amount")
				objTable.fnUpdate(sFields[1], iRow, iIndex, false);

			else if ($(this).text( ) == "Options")
				objTable.fnUpdate(sFields[2], iRow, iIndex, false);
		});


		$(".details").tipTip( );
	}

	else
		objTable.fnStandingRedraw( );


	$.post("ajax/payroll/get-monthly-adjustment-filters.php",
	       {},

	       function (sResponse)
	       {
	       		var sSchool     = "";
	       		var sDepartment = "";
	       		var sMonthYear  = "";


	       		if ($("div.toolbar #School").length > 0)
	       			sSchool = $("div.toolbar #School").val( );

	       		if ($("div.toolbar #Department").length > 0)
	       			sDepartment = $("div.toolbar #Department").val( );

	       		if ($("div.toolbar #MonthYear").length > 0)
	       			sMonthYear = $("div.toolbar #MonthYear").val( );


				$("div.toolbar").html(sResponse);


	       		if ($("div.toolbar #School").length > 0)
	       			$("div.toolbar #School").val(sSchool);

	       		if ($("div.toolbar #Department").length > 0)
	       			$("div.toolbar #Department").val(sDepartment);

	       		if ($("div.toolbar #MonthYear").length > 0)
	       			$("div.toolbar #MonthYear").val(sMonthYear);
	       },

	       "text");
}


function updateAdjustments( )
{
	objTable.fnDestroy( );	


	objTable = $("#DataGrid").dataTable(   { sDom            : '<"H"f<"toolbar"><"TableTools">>t<"F"ip>',
											 aoColumnDefs    : [ { bSortable:false, aTargets:[6] } ],
											 oLanguage       : { sEmptyTable:"No record found", sInfoEmpty:"0 records", sZeroRecords:"No matching record found" },
											 aaSorting       : [ [ 0, "desc" ] ],
											 bJQueryUI       : true,
											 sPaginationType : "full_numbers",
											 bPaginate       : true,
											 bLengthChange   : false,
											 iDisplayLength  : parseInt($("#RecordsPerPage").val( )),
											 bFilter         : true,
											 bSort           : true,
											 bInfo           : true,
											 bStateSave      : false,
											 bProcessing     : false,
											 bAutoWidth      : false,
											 bServerSide     : true,
											 sAjaxSource     : "ajax/payroll/get-monthly-adjustments.php",

											 fnServerData    : function (sSource, aoData, fnCallback)
															   {
																	if ($("div.toolbar #School").length > 0)
																		aoData.push({ name:"School", value:$("div.toolbar #School").val( ) });

																	if ($("div.toolbar #Department").length > 0)
																		aoData.push({ name:"Department", value:$("div.toolbar #Department").val( ) });

																	if ($("div.toolbar #Month").length > 0)
																		aoData.push({ name:"Month", value:$("div.toolbar #Month").val( ) });

																	if ($("div.toolbar #Year").length > 0)
																		aoData.push({ name:"Year", value:$("div.toolbar #Year").val( ) });


																	$.getJSON(sSource, aoData, function(jsonData)
																	{
																		fnCallback(jsonData);


																		$("#DataGrid tbody tr").each(function(iIndex)
																		{
																			$(this).attr("id", $(this).find("img:first-child").attr("id"));
																			$(this).find("td:first-child").addClass("position");

																			if (!$(this).find("img.icnDelete"))
																				$(this).addClass("noDelete");
																		});
																	});


																	if ($("#SelectButtons").length == 1)
																	{
																		if (objTable && objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																			$("#SelectButtons").show( );

																		else
																			$("#SelectButtons").hide( );
																	}
															   },

											 fnDrawCallback  : function( )
															   {
																   $(".details").tipTip( );
															   },

											 fnInitComplete  : function( )
															   {
																	$.post("ajax/payroll/get-monthly-adjustment-filters.php",
																		   {},

																		   function (sResponse)
																		   {
																				$("div.toolbar").html(sResponse);
																		   },

																		   "text");


																	var iSchool     = 0;
																	var iDepartment = 0;
																	var iMonthYear  = 0;

																	$("#DataGrid thead tr th").each(function(iIndex)
																	{
																		if ($(this).text( ) == "School")
																			iSchool = iIndex;

																		if ($(this).text( ) == "Department")
																			iDepartment = iIndex;

																		if ($(this).text( ) == "Month/Year")
																			iMonthYear = iIndex;
																	});

																	this.fnFilter("", iSchool);
																	this.fnFilter("", iDepartment);
																	this.fnFilter("", iMonthYear);
															   }
											 } );
}
